    const stringValue = match[2] ?? match[3];
    const expressionValue = match[4]?.trim();
    if (stringValue !== undefined) {
      props[key] = stringValue;
      continue;
    }
    if (expressionValue === undefined) {
      props[key] = true;
      continue;
    }
    if (expressionValue === "true") {
