","import { access, readFile } from "node:fs/promises";
import { extname, isAbsolute, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { z } from "zod";
import {
  createDiagnostic,
  createDocsError,
  type DocsError,
} from "./diagnostics";
import type { DocsConfig } from "./types";

export interface LoadDocsConfigInput {
  cwd: string;
  configPath?: string;
}

export const DEFAULT_CONFIG_FILENAMES = [
  "docsfn.config.ts",
  "docsfn.config.mjs",
  "docsfn.config.js",
] as const;

const docsVersionConfigSchema = z.object({
  slug: z.string().min(1, "versions.versions[].slug is required"),
  label: z.string().min(1, "versions.versions[].label is required"),
  default: z.boolean().optional(),
});

const docsVersionsSchema = z
  .object({
    mode: z.enum(["none", "path-prefix", "path-segment"]),
    versions: z
      .array(docsVersionConfigSchema)
      .min(1, "versions.versions must contain at least one version"),
  })
  .superRefine((value, context) => {
    const defaultCount = value.versions.filter((version) => version.default).length;
    if (defaultCount > 1) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["versions"],
        message: "versions.versions must mark at most one default version",
      });
    }
  });

const docsTopNavItemSchema: z.ZodType<any> = z.lazy(() =>
  z.object({
    label: z.string().min(1, "navigation.topNav[].label is required"),
    href: z.string().min(1, "navigation.topNav[].href is required"),
    external: z.boolean().optional(),
    children: z.array(docsTopNavItemSchema).optional(),
  })
);

const docsConfigSchema = z.object({
  schemaVersion: z.literal(1, {
    errorMap: () => ({ message: "schemaVersion must be 1" }),
  }),
  site: z.object({
    title: z.string().min(1, "site.title is required"),
    description: z.string().optional(),
    basePath: z
      .string()
      .optional()
      .refine((value) => value === undefined || value.startsWith("/"), "site.basePath must start with '/'"),
    canonicalUrl: z.string().url("site.canonicalUrl must be a valid URL").optional(),
    defaultLocale: z.string().min(1).optional(),
    showFooter: z.boolean().optional(),
    theme: z.record(z.unknown()).optional(),
    editLink: z.record(z.unknown()).optional(),
    pageActions: z.array(z.record(z.unknown())).optional(),
  }),
  compat: z
    .object({
      preset: z.enum(["none", "fumadocs-v15"], {
        errorMap: () => ({
          message: "compat.preset must be one of none or fumadocs-v15",
        }),
      }),
      allowRawHtml: z.literal(false).optional(),
    })
    .optional(),
  versions: docsVersionsSchema.optional(),
  content: z.object({
    root: z.string().min(1, "content.root is required"),
    docsDir: z.string().min(1).optional(),
    pagesDir: z.string().min(1).optional(),
    blogDir: z.string().min(1).optional(),
    apiDir: z.string().min(1).optional(),
    assetsDir: z.string().min(1).optional(),
    metaFileName: z.string().min(1).optional(),
  }),
  navigation: z
    .object({
      topNav: z.array(docsTopNavItemSchema).optional(),
      sidebars: z
        .record(
          z.object({
            title: z.string().optional(),
            root: z.boolean().optional(),
            include: z.array(z.string()).optional(),
          })
        )
        .optional(),
    })
    .optional(),
  search: z
    .object({
      enabled: z.boolean(),
      scopes: z.array(z.enum(["docs", "api", "blog"])),
      bodyIndexing: z.enum(["full", "summary", "disabled"]).optional(),
      maxArtifactBytes: z.number().int().positive().optional(),
      routeScopeOverrides: z
        .array(
          z.object({
            pattern: z.string().min(1, "search.routeScopeOverrides[].pattern is required"),
            scope: z.string().min(1, "search.routeScopeOverrides[].scope is required"),
          })
        )
        .optional(),
    })
    .optional(),
  auth: z
    .object({
      enabled: z.boolean(),
      mode: z.enum(["public", "private", "mixed"]),
    })
    .optional(),
  analytics: z
    .object({
      enabled: z.boolean(),
      provider: z.literal("watchfn"),
      respectDnt: z.boolean(),
    })
    .optional(),
});

export function createDefaultDocsConfig(input: { cwd: string }): DocsConfig {
  return {
    schemaVersion: 1,
    site: {
      title: "Docs",
      basePath: "/docs",
    },
    compat: {
      preset: "none",
    },
    content: {
      root: input.cwd,
      docsDir: "content/docs",
      pagesDir: "pages",
      blogDir: "blog",
      apiDir: "api",
      assetsDir: "public",
      metaFileName: "meta.json",
    },
    search: {
      enabled: true,
      scopes: ["docs"],
      bodyIndexing: "summary",
    },
    auth: {
      enabled: false,
      mode: "public",
    },
    analytics: {
      enabled: false,
      provider: "watchfn",
      respectDnt: true,
    },
  };
}

export async function loadDocsConfig(input: LoadDocsConfigInput): Promise<DocsConfig> {
  const cwd = resolve(input.cwd);
  const discoveredConfigPath = await discoverConfigPath({
    cwd,
    configPath: input.configPath,
  });

  if (!discoveredConfigPath) {
    return createDefaultDocsConfig({ cwd });
  }

  const loadedConfig = await loadConfigModule(discoveredConfigPath);
  return validateDocsConfig(loadedConfig, discoveredConfigPath);
}

async function discoverConfigPath(input: {
  cwd: string;
  configPath?: string;
}): Promise<string | null> {
  if (input.configPath) {
    const explicitPath = isAbsolute(input.configPath)
      ? input.configPath
      : resolve(input.cwd, input.configPath);

    if (!(await fileExists(explicitPath))) {
      throw createDocsError({
        code: "DOCS_CONFIG_INVALID",
        message: `docsfn config file does not exist at ${explicitPath}`,
        diagnostics: [
          createDiagnostic({
            code: "DOCS_CONFIG_INVALID",
            message: `docsfn config file does not exist at ${explicitPath}`,
            location: { absolutePath: explicitPath },
          }),
        ],
      });
    }

    return explicitPath;
  }

  for (const fileName of DEFAULT_CONFIG_FILENAMES) {
    const candidate = resolve(input.cwd, fileName);
    if (await fileExists(candidate)) {
      return candidate;
    }
  }

  return null;
}

async function fileExists(targetPath: string): Promise<boolean> {
  try {
    await access(targetPath);
    return true;
  } catch {
    return false;
  }
}

async function loadConfigModule(configPath: string): Promise<unknown> {
  try {
    if (extname(configPath) === ".ts") {
      return await loadTypeScriptConfig(configPath);
    }

    const moduleValue = await import(pathToFileURL(configPath).href);
    return resolveConfigExport(moduleValue);
  } catch (error) {
    throw createDocsError({
      code: "DOCS_CONFIG_INVALID",
      message: `failed to load docsfn config at ${configPath}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_CONFIG_INVALID",
          message: `failed to load docsfn config at ${configPath}`,
          location: { absolutePath: configPath },
          details: {
            error: error instanceof Error ? error.message : String(error),
          },
        }),
      ],
      cause: error,
    });
  }
}

async function loadTypeScriptConfig(configPath: string): Promise<unknown> {
  try {
    const moduleValue = await import(pathToFileURL(configPath).href);
    return resolveConfigExport(moduleValue);
  } catch {
    const typescriptModuleName = process.env.DOCSFN_TYPESCRIPT_MODULE ?? "typescript";
    const typescript: typeof import("typescript") = await import(
      typescriptModuleName
    );
    const source = await readFile(configPath, "utf8");
    const transpiled = typescript.transpileModule(source, {
      compilerOptions: {
        module: typescript.ModuleKind.ESNext,
        target: typescript.ScriptTarget.ES2022,
      },
      fileName: configPath,
    });
    const dataUrl = `data:text/javascript;base64,${Buffer.from(
      transpiled.outputText
    ).toString("base64")}`;
    const moduleValue = await import(dataUrl);
    return resolveConfigExport(moduleValue);
  }
}

function resolveConfigExport(moduleValue: unknown): unknown {
  const candidate =
    typeof moduleValue === "object" &&
    moduleValue !== null &&
    "default" in moduleValue
      ? (moduleValue as { default: unknown }).default
      : moduleValue;

  return typeof candidate === "function" ? (candidate as () => unknown)() : candidate;
}

function validateDocsConfig(loadedConfig: unknown, configPath: string): DocsConfig {
  const parsed = docsConfigSchema.safeParse(loadedConfig);
  if (parsed.success) {
    return parsed.data as DocsConfig;
  }

  const message = formatConfigValidationMessage(parsed.error.issues);
  const diagnostics = [
    createDiagnostic({
      code: "DOCS_CONFIG_INVALID",
      message,
      location: {
        absolutePath: configPath,
      },
      details: {
        issues: parsed.error.issues.map((issue) => ({
          path: issue.path.join("."),
          message: issue.message,
          code: issue.code,
        })),
      },
    }),
  ];

  throw createDocsError({
    code: "DOCS_CONFIG_INVALID",
    message,
    diagnostics,
  });
}

function formatConfigValidationMessage(
  issues: Array<{ path: Array<string | number>; message: string }>
): string {
  const mappedMessages = issues.map((issue) => {
    const path = issue.path.map(String).join(".");

    if (path === "schemaVersion") {
      return "schemaVersion must be 1";
    }

    if (path === "site.basePath") {
      return "site.basePath must start with '/'";
    }

    if (path === "compat.preset") {
      return "compat.preset must be one of none or fumadocs-v15";
    }

    return path ? `${path} ${issue.message}` : issue.message;
  });

  return Array.from(new Set(mappedMessages)).join(" and ");
}

export function isDocsConfigError(value: unknown): value is DocsError {
  return (
    value instanceof Error &&
    "name" in value &&
    value.name === "DocsError" &&
    "code" in value
  );
}
","import type { DocsDiagnostic, DocsErrorCode } from "./types";

export type LegacyDocsErrorCode =
  | "DOCS_PROVIDER_INVALID"
  | "DOCS_ROUTE_INVALID"
  | "DOCS_COMPILE_FAILED"
  | "DOCS_SEARCH_FAILED";

export type AnyDocsErrorCode = DocsErrorCode | LegacyDocsErrorCode;

const LEGACY_ERROR_CODE_MAP: Record<LegacyDocsErrorCode, DocsErrorCode> = {
  DOCS_PROVIDER_INVALID: "DOCS_PROVIDER_ERROR",
  DOCS_ROUTE_INVALID: "DOCS_ROUTE_NOT_FOUND",
  DOCS_COMPILE_FAILED: "DOCS_MDX_COMPILE_FAILED",
  DOCS_SEARCH_FAILED: "DOCS_SEARCH_BUILD_FAILED",
};

export const CANONICAL_DOCS_ERROR_CODES: DocsErrorCode[] = [
  "DOCS_CONFIG_INVALID",
  "DOCS_CONFIG_UNSUPPORTED",
  "DOCS_PROVIDER_ERROR",
  "DOCS_ENTRY_INVALID",
  "DOCS_META_INVALID",
  "DOCS_ROUTE_CONFLICT",
  "DOCS_ROUTE_NOT_FOUND",
  "DOCS_VERSION_INVALID",
  "DOCS_COMPAT_UNSUPPORTED",
  "DOCS_COMPONENT_UNRESOLVED",
  "DOCS_MDX_COMPILE_FAILED",
  "DOCS_HTML_UNSAFE",
  "DOCS_SEARCH_BUILD_FAILED",
  "DOCS_SEARCH_SCOPE_INVALID",
  "DOCS_OPENAPI_PARSE_FAILED",
  "DOCS_REMOTE_FETCH_FAILED",
  "DOCS_AUTH_REQUIRED",
  "DOCS_AUTH_FORBIDDEN",
  "DOCS_ARTIFACT_INVALID",
];

export function normalizeDocsErrorCode(code: AnyDocsErrorCode): DocsErrorCode {
  if (code in LEGACY_ERROR_CODE_MAP) {
    return LEGACY_ERROR_CODE_MAP[code as LegacyDocsErrorCode];
  }

  return code as DocsErrorCode;
}

export interface CreateDiagnosticInput {
  code: AnyDocsErrorCode;
  severity?: DocsDiagnostic["severity"];
  message: string;
  location?: DocsDiagnostic["location"];
  details?: DocsDiagnostic["details"];
  suggestion?: DocsDiagnostic["suggestion"];
}

export function createDiagnostic(input: CreateDiagnosticInput): DocsDiagnostic {
  return {
    code: normalizeDocsErrorCode(input.code),
    severity: input.severity ?? "error",
    message: input.message,
    location: input.location,
    details: input.details,
    suggestion: input.suggestion,
  };
}

export class DocsError extends Error {
  code: DocsErrorCode;
  diagnostics: DocsDiagnostic[];

  constructor(input: {
    code: AnyDocsErrorCode;
    message: string;
    diagnostics: DocsDiagnostic[];
    cause?: unknown;
  }) {
    super(input.message, { cause: input.cause });
    this.name = "DocsError";
    this.code = normalizeDocsErrorCode(input.code);
    this.diagnostics = input.diagnostics;
  }
}

export function createDocsError(input: {
  code: AnyDocsErrorCode;
  message: string;
  diagnostics?: DocsDiagnostic[];
  cause?: unknown;
}): DocsError {
  const diagnostics =
    input.diagnostics && input.diagnostics.length > 0
      ? input.diagnostics
      : [createDiagnostic({ code: input.code, message: input.message })];

  return new DocsError({
    code: input.code,
    message: input.message,
    diagnostics,
    cause: input.cause,
  });
}

export function hasErrorDiagnostics(diagnostics: DocsDiagnostic[]): boolean {
  return diagnostics.some((diagnostic) => diagnostic.severity === "error");
}

const SENSITIVE_DETAIL_KEY_PATTERN =
  /(secret|token|cookie|authorization|password|passwd|api[-_]?key|private[-_]?key|raw[-_]?body|raw[-_]?content|session)/i;

const SENSITIVE_DETAIL_VALUE_PATTERN =
  /(bearer\s+[a-z0-9._-]+|xox[baprs]-[a-z0-9-]+|gh[pousr]_[a-z0-9]+|sk_[a-z0-9]+)/i;

function redactDiagnosticValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => redactDiagnosticValue(item));
  }

  if (typeof value === "string") {
    return SENSITIVE_DETAIL_VALUE_PATTERN.test(value) ? "[REDACTED]" : value;
  }

  if (typeof value !== "object" || value === null) {
    return value;
  }

  const output: Record<string, unknown> = {};
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    if (SENSITIVE_DETAIL_KEY_PATTERN.test(key)) {
      output[key] = "[REDACTED]";
      continue;
    }
    output[key] = redactDiagnosticValue(nested);
  }

  return output;
}

export function redactDiagnostics(
  diagnostics: DocsDiagnostic[]
): DocsDiagnostic[] {
  return diagnostics.map((diagnostic) => ({
    ...diagnostic,
    details:
      diagnostic.details === undefined
        ? undefined
        : (redactDiagnosticValue(diagnostic.details) as Record<string, unknown>),
  }));
}

export function formatDiagnosticsForCli(
  diagnostics: DocsDiagnostic[]
): string[] {
  return diagnostics.map((diagnostic) => {
    const locationParts: string[] = [];
    if (diagnostic.location?.sourceId) {
      locationParts.push(`source=${diagnostic.location.sourceId}`);
    }
    if (diagnostic.location?.absolutePath) {
      locationParts.push(`path=${diagnostic.location.absolutePath}`);
    }
    if (typeof diagnostic.location?.line === "number") {
      locationParts.push(`line=${diagnostic.location.line}`);
    }
    if (typeof diagnostic.location?.column === "number") {
      locationParts.push(`column=${diagnostic.location.column}`);
    }
    const locationSuffix =
      locationParts.length > 0 ? ` (${locationParts.join(", ")})` : "";
    return `[${diagnostic.severity.toUpperCase()}] ${diagnostic.code}: ${diagnostic.message}${locationSuffix}`;
  });
}

export function diagnosticsFromUnknownError(
  error: unknown,
  fallback: {
    code: AnyDocsErrorCode;
    message: string;
  }
): DocsDiagnostic[] {
  if (
    typeof error === "object" &&
    error !== null &&
    "diagnostics" in error &&
    Array.isArray((error as { diagnostics?: unknown }).diagnostics)
  ) {
    return (error as { diagnostics: DocsDiagnostic[] }).diagnostics;
  }

  return [
    createDiagnostic({
      code: fallback.code,
      message:
        error instanceof Error && error.message
          ? `${fallback.message}: ${error.message}`
          : fallback.message,
    }),
  ];
}

export function assertNoErrorDiagnostics(
  diagnostics: DocsDiagnostic[],
  message = "docsfn encountered diagnostics with error severity"
): void {
  if (!hasErrorDiagnostics(diagnostics)) {
    return;
  }

  const firstError =
    diagnostics.find((diagnostic) => diagnostic.severity === "error") ??
    diagnostics[0];

  throw createDocsError({
    code: firstError.code,
    message,
    diagnostics,
  });
}
","import { createHash } from "node:crypto";
import { posix } from "node:path";
import { createDiagnostic, createDocsError } from "./diagnostics";
import type {
  DocsCollection,
  DocsConfig,
  DocsDiagnostic,
  RawContentEntry,
} from "./types";

export type DocsSourceEntryType = "content" | "control" | "asset";

export interface DocsSourceEntry {
  id: string;
  collection: DocsCollection;
  relativePath: string;
  absolutePath?: string;
  entryType: DocsSourceEntryType;
  frontmatter: Record<string, unknown>;
  body?: string;
  bytes?: number;
  sha256?: string;
  etag?: string;
  updatedAt?: string;
  meta?: Record<string, unknown>;
}

export interface DocsProviderListEntriesInput {
  config: DocsConfig;
  collections: DocsCollection[];
}

export interface DocsProviderLoadEntryInput {
  config: DocsConfig;
  entry: DocsSourceEntry;
}

export interface DocsProviderLoadAssetResult {
  relativePath: string;
  absolutePath: string;
  bytes: number;
  sha256?: string;
}

export interface DocsProviderWatchMetadata {
  watchedFiles: string[];
  watchedDirectories: string[];
  collectionGlobs: Partial<Record<DocsCollection, string[]>>;
}

export interface DocsProviderWatchInput {
  config: DocsConfig;
  onChange: (paths: string[]) => Promise<void> | void;
  collections?: DocsCollection[];
}

export interface DocsProviderWatchSubscription {
  metadata: DocsProviderWatchMetadata;
  close(): Promise<void>;
}

export interface DocsContentProvider {
  readonly providerId: string;
  listEntries(input: DocsProviderListEntriesInput): Promise<DocsSourceEntry[]>;
  loadEntry(input: DocsProviderLoadEntryInput): Promise<DocsSourceEntry>;
  loadAsset?(input: {
    config: DocsConfig;
    relativePath: string;
  }): Promise<DocsProviderLoadAssetResult>;
  watch?(input: DocsProviderWatchInput): Promise<DocsProviderWatchSubscription>;
  list(): Promise<RawContentEntry[]>;
}

export function normalizeProviderPath(inputPath: string): string {
  return inputPath
    .replaceAll("\\", "/")
    .split("/")
    .filter((segment) => segment.length > 0 && segment !== ".")
    .map((segment) => segment.normalize("NFC"))
    .join("/");
}

export function createSourceEntryId(
  collection: DocsCollection,
  relativePath: string
): string {
  return `${collection}:${normalizeProviderPath(relativePath)}`;
}

export function stableSortSourceEntries(entries: DocsSourceEntry[]): DocsSourceEntry[] {
  return [...entries].sort((left, right) => {
    const leftKey = `${left.collection}:${normalizeProviderPath(left.relativePath)}`;
    const rightKey = `${right.collection}:${normalizeProviderPath(right.relativePath)}`;
    return leftKey.localeCompare(rightKey, "en", {
      sensitivity: "variant",
      numeric: true,
    });
  });
}

export function assertUniqueSourceEntryIds(entries: DocsSourceEntry[]): void {
  const seen = new Map<string, DocsSourceEntry>();
  for (const entry of entries) {
    const existing = seen.get(entry.id);
    if (existing) {
      throw createDocsError({
        code: "DOCS_PROVIDER_ERROR",
        message: `provider emitted duplicate source entry id ${entry.id}`,
        diagnostics: [
          createDiagnostic({
            code: "DOCS_PROVIDER_ERROR",
            message: `provider emitted duplicate source entry id ${entry.id}`,
            details: {
              duplicateId: entry.id,
              firstPath: existing.relativePath,
              secondPath: entry.relativePath,
            },
          }),
        ],
      });
    }
    seen.set(entry.id, entry);
  }
}

export function validateSourceEntries(entries: DocsSourceEntry[]): DocsDiagnostic[] {
  const diagnostics: DocsDiagnostic[] = [];

  for (const entry of entries) {
    const normalizedRelativePath = normalizeProviderPath(entry.relativePath);
    if (!entry.id || entry.id.trim().length === 0) {
      diagnostics.push(
        createDiagnostic({
          code: "DOCS_PROVIDER_ERROR",
          message: "provider entry id is required",
          location: { absolutePath: entry.absolutePath },
        })
      );
    }

    if (!entry.collection) {
      diagnostics.push(
        createDiagnostic({
          code: "DOCS_PROVIDER_ERROR",
          message: `provider entry ${entry.id} is missing collection`,
          location: { absolutePath: entry.absolutePath },
        })
      );
    }

    if (normalizedRelativePath.length === 0) {
      diagnostics.push(
        createDiagnostic({
          code: "DOCS_PROVIDER_ERROR",
          message: `provider entry ${entry.id} has empty relativePath`,
          location: { absolutePath: entry.absolutePath },
        })
      );
    }

    if (entry.relativePath !== normalizedRelativePath) {
      diagnostics.push(
        createDiagnostic({
          code: "DOCS_PROVIDER_ERROR",
          severity: "warning",
          message: `provider entry ${entry.id} relativePath is not normalized`,
          location: { absolutePath: entry.absolutePath },
          details: {
            actual: entry.relativePath,
            normalized: normalizedRelativePath,
          },
        })
      );
    }
  }

  return diagnostics;
}

export function assertValidSourceEntries(entries: DocsSourceEntry[]): DocsSourceEntry[] {
  assertUniqueSourceEntryIds(entries);
  const diagnostics = validateSourceEntries(entries);
  const errorDiagnostics = diagnostics.filter(
    (diagnostic) => diagnostic.severity === "error"
  );
  if (errorDiagnostics.length > 0) {
    throw createDocsError({
      code: "DOCS_PROVIDER_ERROR",
      message: "provider entries failed validation",
      diagnostics: errorDiagnostics,
    });
  }

  return stableSortSourceEntries(entries);
}

export function createProviderError(input: {
  message: string;
  absolutePath?: string;
  details?: Record<string, unknown>;
}) {
  return createDocsError({
    code: "DOCS_PROVIDER_ERROR",
    message: input.message,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_PROVIDER_ERROR",
        message: input.message,
        location: { absolutePath: input.absolutePath },
        details: input.details,
      }),
    ],
  });
}

export function createProviderRemoteFetchError(input: {
  message: string;
  absolutePath?: string;
  details?: Record<string, unknown>;
}) {
  return createDocsError({
    code: "DOCS_REMOTE_FETCH_FAILED",
    message: input.message,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_REMOTE_FETCH_FAILED",
        message: input.message,
        location: { absolutePath: input.absolutePath },
        details: input.details,
      }),
    ],
  });
}

export function sha256FromBuffer(buffer: Buffer): string {
  return createHash("sha256").update(buffer).digest("hex");
}

export function normalizeToPosixPath(value: string): string {
  return posix.normalize(normalizeProviderPath(value));
}

export function toLegacyRawEntries(entries: DocsSourceEntry[]): RawContentEntry[] {
  return stableSortSourceEntries(entries)
    .filter((entry) => entry.entryType !== "control")
    .map((entry) => {
      const kind =
        entry.collection === "api"
          ? "api"
          : entry.collection === "blog"
            ? "post"
            : entry.collection === "assets"
              ? "asset"
              : "page";

      return {
        id: normalizeProviderPath(entry.relativePath),
        kind,
        body: entry.body ?? "",
        frontmatter: entry.frontmatter,
        filepath: entry.absolutePath,
      } as RawContentEntry;
    });
}
","import { createDiagnostic, createDocsError } from "./diagnostics";
import type { NormalizedPostRecord } from "./normalize";
import type {
  BlogArchivePage,
  BlogManifestSurface,
  BlogPost,
  BlogTagIndex,
} from "./types";

export interface BuildCanonicalBlogRecordsInput {
  posts: NormalizedPostRecord[];
  basePath?: string;
  preview?: boolean;
  pageSize?: number;
}

export interface CanonicalBlogBuildResult extends BlogManifestSurface {
  posts: BlogPost[];
}

function compareStrings(left: string, right: string): number {
  return left.localeCompare(right, "en", {
    sensitivity: "variant",
    numeric: true,
  });
}

function normalizeBasePath(basePath?: string): string {
  const value = typeof basePath === "string" && basePath.length > 0 ? basePath : "/docs";
  const prefixed = value.startsWith("/") ? value : `/${value}`;
  return prefixed.length > 1 ? prefixed.replace(/\/+$/, "") : prefixed;
}

function stripMarkdown(source: string): string {
  return source
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/`[^`]*`/g, " ")
    .replace(/\[(.*?)\]\((.*?)\)/g, "$1")
    .replace(/<\/?[^>]+>/g, " ")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/[*_~>-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function summarize(source: string, maxLength = 220): string {
  const normalized = stripMarkdown(source);
  if (normalized.length <= maxLength) {
    return normalized;
  }
  return `${normalized.slice(0, maxLength - 1).trimEnd()}…`;
}

function toTagSlug(value: string): string {
  const normalized = value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return normalized.length > 0 ? normalized : "tag";
}

function normalizeTags(tags: string[]): string[] {
  const seen = new Set<string>();
  const normalized: string[] = [];
  for (const tag of tags) {
    const canonical = tag.trim().toLowerCase();
    if (!canonical || seen.has(canonical)) {
      continue;
    }
    seen.add(canonical);
    normalized.push(canonical);
  }
  return normalized.sort(compareStrings);
}

function parseDraftFlag(value: unknown): boolean {
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    return normalized === "true" || normalized === "yes" || normalized === "1";
  }
  if (typeof value === "number") {
    return value === 1;
  }
  return false;
}

function parseAuthor(frontmatter: Record<string, unknown>): string | undefined {
  const rawAuthor = frontmatter.author;
  if (typeof rawAuthor === "string" && rawAuthor.trim().length > 0) {
    return rawAuthor.trim();
  }
  if (typeof rawAuthor === "object" && rawAuthor !== null) {
    const fromObject =
      typeof (rawAuthor as { name?: unknown }).name === "string"
        ? String((rawAuthor as { name: string }).name).trim()
        : "";
    if (fromObject.length > 0) {
      return fromObject;
    }
  }
  return undefined;
}

function parseExcerpt(input: {
  excerpt?: unknown;
  body: string;
}): string | undefined {
  if (typeof input.excerpt === "string" && input.excerpt.trim().length > 0) {
    return input.excerpt.trim();
  }
  const summary = summarize(input.body);
  return summary.length > 0 ? summary : undefined;
}

function parsePublishedDate(input: { date: string; sourceId: string }): {
  date: string;
  publishedAt: string;
  timestamp: number;
} {
  const timestamp = Date.parse(input.date);
  if (!Number.isFinite(timestamp)) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `blog post ${input.sourceId} has invalid publish date metadata`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `blog post ${input.sourceId} has invalid publish date metadata`,
          details: {
            sourceId: input.sourceId,
            date: input.date,
          },
        }),
      ],
    });
  }

  const published = new Date(timestamp).toISOString();
  return {
    date: published.slice(0, 10),
    publishedAt: published,
    timestamp,
  };
}

function buildArchivePages(input: {
  orderedPosts: BlogPost[];
  listRoute: string;
  pageSize: number;
}): BlogArchivePage[] {
  const totalPosts = input.orderedPosts.length;
  const totalPages = Math.max(1, Math.ceil(totalPosts / input.pageSize));
  const pages: BlogArchivePage[] = [];

  for (let page = 1; page <= totalPages; page += 1) {
    const start = (page - 1) * input.pageSize;
    const slice = input.orderedPosts.slice(start, start + input.pageSize);
    pages.push({
      page,
      path: page === 1 ? input.listRoute : `${input.listRoute}/page/${page}`,
      postIds: slice.map((post) => post.id),
      totalPages,
      totalPosts,
      pageSize: input.pageSize,
    });
  }

  return pages;
}

function buildTagIndexes(input: {
  orderedPosts: BlogPost[];
  listRoute: string;
}): Record<string, BlogTagIndex> {
  const tagMap = new Map<string, BlogTagIndex>();
  for (const post of input.orderedPosts) {
    for (const tag of post.tags) {
      const slug = toTagSlug(tag);
      const existing = tagMap.get(tag);
      if (existing) {
        existing.postIds.push(post.id);
        continue;
      }
      tagMap.set(tag, {
        tag,
        slug,
        path: `${input.listRoute}/tags/${slug}`,
        postIds: [post.id],
      });
    }
  }

  return Object.fromEntries(
    [...tagMap.entries()].sort(([left], [right]) => compareStrings(left, right))
  );
}

export function assertValidBlogPublishMetadata(post: Pick<BlogPost, "id" | "date">): {
  date: string;
  publishedAt: string;
  timestamp: number;
} {
  return parsePublishedDate({
    date: post.date,
    sourceId: post.id,
  });
}

export function resolveBlogLastBuildDate(posts: Array<Pick<BlogPost, "id" | "date">>): string {
  if (posts.length === 0) {
    return new Date("1970-01-01T00:00:00.000Z").toUTCString();
  }

  const latest = [...posts]
    .map((post) => ({
      id: post.id,
      ...assertValidBlogPublishMetadata(post),
    }))
    .sort((left, right) => {
      if (left.timestamp !== right.timestamp) {
        return right.timestamp - left.timestamp;
      }
      return compareStrings(left.id, right.id);
    })[0];

  return new Date(latest.publishedAt).toUTCString();
}

export function buildCanonicalBlogRecords(
  input: BuildCanonicalBlogRecordsInput
): CanonicalBlogBuildResult {
  const basePath = normalizeBasePath(input.basePath);
  const listRoute = `${basePath}/blog`;
  const feedPath = `${listRoute}/rss.xml`;
  const includeDrafts = Boolean(input.preview);
  const pageSize = Math.max(1, Math.trunc(input.pageSize ?? 10));

  const canonicalPosts = input.posts
    .map((post) => {
      const frontmatterDate = post.frontmatter?.date;
      if (!(typeof frontmatterDate === "string" && frontmatterDate.trim().length > 0)) {
        throw createDocsError({
          code: "DOCS_ARTIFACT_INVALID",
          message: `blog post ${post.id} is missing publish date metadata`,
          diagnostics: [
            createDiagnostic({
              code: "DOCS_ARTIFACT_INVALID",
              message: `blog post ${post.id} is missing publish date metadata`,
              details: {
                sourceId: post.id,
              },
            }),
          ],
        });
      }

      const draft = parseDraftFlag(post.frontmatter?.draft);
      const publish = parsePublishedDate({
        date: frontmatterDate,
        sourceId: post.id,
      });
      const tags = normalizeTags(post.tags);
      const excerpt = parseExcerpt({
        excerpt: post.frontmatter?.excerpt,
        body: post.body,
      });

      return {
        kind: "post" as const,
        id: post.id,
        slug: post.slug,
        path: post.slug ? `${listRoute}/${post.slug}` : listRoute,
        title: post.title,
        date: publish.date,
        publishedAt: publish.publishedAt,
        author: parseAuthor(post.frontmatter),
        excerpt,
        summary: excerpt ?? summarize(post.body),
        draft,
        tags,
        body: post.body,
        frontmatter: post.frontmatter,
        _sortTimestamp: publish.timestamp,
      };
    })
    .filter((post) => includeDrafts || !post.draft)
    .sort((left, right) => {
      if (left._sortTimestamp !== right._sortTimestamp) {
        return right._sortTimestamp - left._sortTimestamp;
      }
      const slugCompare = compareStrings(left.slug, right.slug);
      if (slugCompare !== 0) {
        return slugCompare;
      }
      return compareStrings(left.id, right.id);
    });

  const posts = canonicalPosts.map(({ _sortTimestamp, ...post }) => post);
  const tags = buildTagIndexes({ orderedPosts: posts, listRoute });
  const archives = buildArchivePages({
    orderedPosts: posts,
    listRoute,
    pageSize,
  });
  const postOrder = posts.map((post) => post.id);

  return {
    posts,
    listRoute,
    feedPath,
    postOrder,
    tags,
    archives,
  };
}
","import { parse as parseYaml } from "yaml";
import { createDiagnostic, createDocsError } from "./diagnostics";
import { deriveLogicalPathFromSourcePath, normalizeSlug, stripSourceExtension } from "./routing";
import type { DocsDiagnostic } from "./types";

const HTTP_METHOD_ORDER = [
  "get",
  "post",
  "put",
  "patch",
  "delete",
  "options",
  "head",
  "trace",
] as const;

const HTTP_METHOD_SET = new Set<string>(HTTP_METHOD_ORDER);

export type OpenApiSourceFormat = "json" | "yaml";

export interface CanonicalOpenApiExample {
  name: string;
  summary?: string;
  description?: string;
  value: unknown;
}

export interface CanonicalOpenApiParameter {
  name: string;
  in: string;
  required: boolean;
  description?: string;
  schema?: unknown;
  schemaType?: string;
  example?: unknown;
}

export interface CanonicalOpenApiRequestBodyMedia {
  mediaType: string;
  schema?: unknown;
  example?: unknown;
  examples: CanonicalOpenApiExample[];
}

export interface CanonicalOpenApiRequestBody {
  required: boolean;
  description?: string;
  content: CanonicalOpenApiRequestBodyMedia[];
}

export interface CanonicalOpenApiResponse {
  statusCode: string;
  description?: string;
  content: CanonicalOpenApiRequestBodyMedia[];
}

export interface CanonicalOpenApiOperation {
  id: string;
  operationId?: string;
  method: Uppercase<(typeof HTTP_METHOD_ORDER)[number]>;
  methodLower: (typeof HTTP_METHOD_ORDER)[number];
  path: string;
  routePath: string;
  summary?: string;
  description?: string;
  tags: string[];
  parameters: CanonicalOpenApiParameter[];
  requestBody?: CanonicalOpenApiRequestBody;
  responses: CanonicalOpenApiResponse[];
  deprecated: boolean;
}

export interface CanonicalOpenApiTagGroup {
  slug: string;
  name: string;
  description?: string;
  routePath: string;
  operationIds: string[];
}

export interface CanonicalOpenApiSchemaRecord {
  name: string;
  slug: string;
  routePath: string;
  description?: string;
  schema: unknown;
}

export interface CanonicalOpenApiServer {
  url: string;
  description?: string;
}

export interface CanonicalOpenApiRoutes {
  overview: string;
  tags: Record<string, string>;
  operations: Record<string, string>;
  schemas: Record<string, string>;
  all: string[];
}

export interface CanonicalOpenApiReference {
  schemaVersion: 1;
  sourceId: string;
  sourcePath: string;
  sourceFormat: OpenApiSourceFormat;
  openapiVersion: string;
  title: string;
  description?: string;
  version?: string;
  info: {
    title: string;
    description?: string;
    version?: string;
  };
  servers: CanonicalOpenApiServer[];
  tags: CanonicalOpenApiTagGroup[];
  operations: CanonicalOpenApiOperation[];
  schemas: CanonicalOpenApiSchemaRecord[];
  routes: CanonicalOpenApiRoutes;
  diagnostics: DocsDiagnostic[];
  sourceMeta: {
    etag?: string;
    sha256?: string;
    updatedAt?: string;
    remoteUrl?: string;
  };
}

export interface ParseOpenApiSourceInput {
  sourceId: string;
  sourcePath: string;
  body: string;
  absolutePath?: string;
}

export interface NormalizeOpenApiReferenceInput {
  sourceId: string;
  sourcePath: string;
  parsed: unknown;
  sourceFormat: OpenApiSourceFormat;
  fallbackTitle: string;
  basePath?: string;
  sourceMeta?: CanonicalOpenApiReference["sourceMeta"];
}

export interface BuildOpenApiReferenceInput {
  sourceId: string;
  sourcePath: string;
  body: string;
  fallbackTitle: string;
  basePath?: string;
  absolutePath?: string;
  sourceMeta?: CanonicalOpenApiReference["sourceMeta"];
}

const OPENAPI_VERSION_REGEX = /^3(?:\.\d+){1,2}$/;

function compareStrings(left: string, right: string): number {
  return left.localeCompare(right, "en", {
    sensitivity: "variant",
    numeric: true,
  });
}

function normalizeBasePath(basePath: string | undefined): string {
  const value = typeof basePath === "string" && basePath.length > 0 ? basePath : "/docs";
  const prefixed = value.startsWith("/") ? value : `/${value}`;
  return prefixed.length > 1 ? prefixed.replace(/\/+$/, "") : prefixed;
}

function normalizeRouteSlug(value: string): string {
  const normalized = value
    .toLowerCase()
    .replaceAll("{", "")
    .replaceAll("}", "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return normalized.length > 0 ? normalized : "item";
}

function toObject(value: unknown): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return {};
  }
  return value as Record<string, unknown>;
}

function resolveSourceFormat(sourcePath: string): OpenApiSourceFormat {
  const normalized = normalizeSlug(sourcePath).toLowerCase();
  if (normalized.endsWith(".json")) {
    return "json";
  }
  return "yaml";
}

function createOpenApiParseError(input: {
  message: string;
  sourceId: string;
  sourcePath: string;
  absolutePath?: string;
  details?: Record<string, unknown>;
  cause?: unknown;
}) {
  return createDocsError({
    code: "DOCS_OPENAPI_PARSE_FAILED",
    message: input.message,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_OPENAPI_PARSE_FAILED",
        message: input.message,
        location: {
          sourceId: input.sourceId,
          absolutePath: input.absolutePath,
        },
        details: {
          sourcePath: input.sourcePath,
          ...(input.details ?? {}),
        },
      }),
    ],
    cause: input.cause,
  });
}

function parseJson(source: ParseOpenApiSourceInput): unknown {
  try {
    return JSON.parse(source.body);
  } catch (error) {
    throw createOpenApiParseError({
      message: `OpenAPI JSON source ${source.sourcePath} could not be parsed`,
      sourceId: source.sourceId,
      sourcePath: source.sourcePath,
      absolutePath: source.absolutePath,
      details: {
        parser: "json",
        error: error instanceof Error ? error.message : String(error),
      },
      cause: error,
    });
  }
}

function parseYamlSource(source: ParseOpenApiSourceInput): unknown {
  try {
    return parseYaml(source.body);
  } catch (error) {
    throw createOpenApiParseError({
      message: `OpenAPI YAML source ${source.sourcePath} could not be parsed`,
      sourceId: source.sourceId,
      sourcePath: source.sourcePath,
      absolutePath: source.absolutePath,
      details: {
        parser: "yaml",
        error: error instanceof Error ? error.message : String(error),
      },
      cause: error,
    });
  }
}

function normalizeExamples(value: unknown): CanonicalOpenApiExample[] {
  const record = toObject(value);
  return Object.keys(record)
    .sort(compareStrings)
    .map((name) => {
      const item = toObject(record[name]);
      return {
        name,
        summary: typeof item.summary === "string" ? item.summary : undefined,
        description: typeof item.description === "string" ? item.description : undefined,
        value: "value" in item ? item.value : undefined,
      };
    });
}

function normalizeMediaContent(value: unknown): CanonicalOpenApiRequestBodyMedia[] {
  const contentRecord = toObject(value);
  return Object.keys(contentRecord)
    .sort(compareStrings)
    .map((mediaType) => {
      const media = toObject(contentRecord[mediaType]);
      return {
        mediaType,
        schema: media.schema,
        example: media.example,
        examples: normalizeExamples(media.examples),
      };
    });
}

function normalizeParameter(value: unknown): CanonicalOpenApiParameter {
  const parameter = toObject(value);
  const schema = toObject(parameter.schema);
  const fromRef =
    typeof parameter.$ref === "string"
      ? parameter.$ref.split("/").filter(Boolean).at(-1)
      : undefined;

  return {
    name:
      typeof parameter.name === "string" && parameter.name.length > 0
        ? parameter.name
        : fromRef ?? "param",
    in: typeof parameter.in === "string" && parameter.in.length > 0 ? parameter.in : "query",
    required: Boolean(parameter.required),
    description:
      typeof parameter.description === "string" ? parameter.description : undefined,
    schema: Object.keys(schema).length > 0 ? schema : undefined,
    schemaType: typeof schema.type === "string" ? schema.type : undefined,
    example: "example" in parameter ? parameter.example : undefined,
  };
}

function normalizeRequestBody(value: unknown): CanonicalOpenApiRequestBody | undefined {
  const requestBody = toObject(value);
  if (Object.keys(requestBody).length === 0) {
    return undefined;
  }

  return {
    required: Boolean(requestBody.required),
    description:
      typeof requestBody.description === "string" ? requestBody.description : undefined,
    content: normalizeMediaContent(requestBody.content),
  };
}

function normalizeResponses(value: unknown): CanonicalOpenApiResponse[] {
  const responses = toObject(value);
  return Object.keys(responses)
    .sort(compareStrings)
    .map((statusCode) => {
      const response = toObject(responses[statusCode]);
      return {
        statusCode,
        description:
          typeof response.description === "string" ? response.description : undefined,
        content: normalizeMediaContent(response.content),
      };
    });
}

function operationSort(left: CanonicalOpenApiOperation, right: CanonicalOpenApiOperation): number {
  const methodWeight =
    HTTP_METHOD_ORDER.indexOf(left.methodLower) -
    HTTP_METHOD_ORDER.indexOf(right.methodLower);
  if (methodWeight !== 0) {
    return methodWeight;
  }
  const pathComparison = compareStrings(left.path, right.path);
  if (pathComparison !== 0) {
    return pathComparison;
  }
  return compareStrings(left.id, right.id);
}

function buildApiRootPath(basePath: string, sourcePath: string): string {
  const logicalPath = deriveLogicalPathFromSourcePath(stripSourceExtension(sourcePath));
  if (!logicalPath) {
    return `${basePath}/api`;
  }
  return `${basePath}/api/${logicalPath}`;
}

function assertOpenApi3x(parsed: Record<string, unknown>, input: NormalizeOpenApiReferenceInput): string {
  const version =
    typeof parsed.openapi === "string" && parsed.openapi.length > 0
      ? parsed.openapi
      : "";
  if (!OPENAPI_VERSION_REGEX.test(version) || !version.startsWith("3.")) {
    throw createOpenApiParseError({
      message: `unsupported OpenAPI version ${version || "unknown"} for ${input.sourcePath}; only 3.x is supported`,
      sourceId: input.sourceId,
      sourcePath: input.sourcePath,
      details: {
        openapi: parsed.openapi,
      },
    });
  }
  return version;
}

export function parseOpenApiSource(input: ParseOpenApiSourceInput): {
  sourceFormat: OpenApiSourceFormat;
  parsed: unknown;
} {
  const sourceFormat = resolveSourceFormat(input.sourcePath);
  const parsed = sourceFormat === "json" ? parseJson(input) : parseYamlSource(input);

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw createOpenApiParseError({
      message: `OpenAPI source ${input.sourcePath} must parse to an object`,
      sourceId: input.sourceId,
      sourcePath: input.sourcePath,
      absolutePath: input.absolutePath,
      details: {
        parsedType: Array.isArray(parsed) ? "array" : typeof parsed,
      },
    });
  }

  return {
    sourceFormat,
    parsed,
  };
}

export function normalizeOpenApiReference(
  input: NormalizeOpenApiReferenceInput
): CanonicalOpenApiReference {
  const parsed = toObject(input.parsed);
  const diagnostics: DocsDiagnostic[] = [];
  const openapiVersion = assertOpenApi3x(parsed, input);

  if (parsed.webhooks) {
    diagnostics.push(
      createDiagnostic({
        code: "DOCS_ARTIFACT_INVALID",
        severity: "warning",
        message: `OpenAPI source ${input.sourcePath} includes webhooks which are not rendered by docsfn yet`,
        details: {
          sourceId: input.sourceId,
          sourcePath: input.sourcePath,
          unsupported: "webhooks",
        },
      })
    );
  }

  const info = toObject(parsed.info);
  const title =
    (typeof info.title === "string" && info.title) || input.fallbackTitle;
  const basePath = normalizeBasePath(input.basePath);
  const apiRootPath = buildApiRootPath(basePath, input.sourcePath);

  const servers = (Array.isArray(parsed.servers) ? parsed.servers : [])
    .map((value) => toObject(value))
    .filter((value) => typeof value.url === "string" && value.url.length > 0)
    .map((server) => ({
      url: String(server.url),
      description: typeof server.description === "string" ? server.description : undefined,
    }))
    .sort((left, right) => compareStrings(left.url, right.url));

  const operationIds = new Set<string>();
  const operations: CanonicalOpenApiOperation[] = [];
  const tagMap = new Map<string, { description?: string; operationIds: string[] }>();

  const declaredTags = Array.isArray(parsed.tags) ? parsed.tags : [];
  for (const tag of declaredTags) {
    const normalized = toObject(tag);
    if (typeof normalized.name !== "string" || normalized.name.length === 0) {
      continue;
    }
    const name = normalized.name;
    tagMap.set(name, {
      description:
        typeof normalized.description === "string" ? normalized.description : undefined,
      operationIds: [],
    });
  }

  const paths = toObject(parsed.paths);
  for (const pathKey of Object.keys(paths).sort(compareStrings)) {
    const pathItem = paths[pathKey];
    if (typeof pathItem !== "object" || pathItem === null || Array.isArray(pathItem)) {
      throw createOpenApiParseError({
        message: `OpenAPI source ${input.sourcePath} has malformed path operations at ${pathKey}`,
        sourceId: input.sourceId,
        sourcePath: input.sourcePath,
      });
    }

    const pathRecord = pathItem as Record<string, unknown>;
    const pathParameters = Array.isArray(pathRecord.parameters)
      ? pathRecord.parameters.map(normalizeParameter)
      : [];

    for (const method of Object.keys(pathRecord).sort(compareStrings)) {
      if (!HTTP_METHOD_SET.has(method.toLowerCase())) {
        continue;
      }

      const methodLower = method.toLowerCase() as (typeof HTTP_METHOD_ORDER)[number];
      const operationRaw = pathRecord[method];
      if (
        typeof operationRaw !== "object" ||
        operationRaw === null ||
        Array.isArray(operationRaw)
      ) {
        throw createOpenApiParseError({
          message: `OpenAPI source ${input.sourcePath} has malformed ${method.toUpperCase()} ${pathKey} operation`,
          sourceId: input.sourceId,
          sourcePath: input.sourcePath,
        });
      }

      const operation = operationRaw as Record<string, unknown>;
      const explicitOperationId =
        typeof operation.operationId === "string" && operation.operationId.length > 0
          ? operation.operationId
          : undefined;

      if (explicitOperationId) {
        if (operationIds.has(explicitOperationId)) {
          throw createOpenApiParseError({
            message: `OpenAPI source ${input.sourcePath} has duplicate operationId ${explicitOperationId}`,
            sourceId: input.sourceId,
            sourcePath: input.sourcePath,
          });
        }
        operationIds.add(explicitOperationId);
      }

      const pathSlug = normalizeRouteSlug(pathKey);
      const operationSlug = explicitOperationId
        ? normalizeRouteSlug(explicitOperationId)
        : pathSlug;
      const routePath = `${apiRootPath}/operations/${methodLower}-${operationSlug}`;

      const localParameters = Array.isArray(operation.parameters)
        ? operation.parameters.map(normalizeParameter)
        : [];
      const mergedParameterMap = new Map<string, CanonicalOpenApiParameter>();
      for (const parameter of [...pathParameters, ...localParameters]) {
        mergedParameterMap.set(`${parameter.in}:${parameter.name}`, parameter);
      }

      const operationTags = Array.isArray(operation.tags)
        ? operation.tags.filter((value): value is string => typeof value === "string")
        : [];
      const normalizedTags = (operationTags.length > 0 ? operationTags : ["default"])
        .map((tag) => tag.trim())
        .filter((tag) => tag.length > 0)
        .sort(compareStrings);

      const operationId = explicitOperationId ?? `${methodLower}:${pathKey}`;
      operations.push({
        id: operationId,
        operationId: explicitOperationId,
        method: methodLower.toUpperCase() as Uppercase<(typeof HTTP_METHOD_ORDER)[number]>,
        methodLower,
        path: pathKey,
        routePath,
        summary: typeof operation.summary === "string" ? operation.summary : undefined,
        description:
          typeof operation.description === "string" ? operation.description : undefined,
        tags: normalizedTags,
        parameters: [...mergedParameterMap.values()].sort((left, right) => {
          const locationComparison = compareStrings(left.in, right.in);
          if (locationComparison !== 0) {
            return locationComparison;
          }
          return compareStrings(left.name, right.name);
        }),
        requestBody: normalizeRequestBody(operation.requestBody),
        responses: normalizeResponses(operation.responses),
        deprecated: Boolean(operation.deprecated),
      });

      for (const tagName of normalizedTags) {
        const current = tagMap.get(tagName) ?? { operationIds: [] as string[] };
        current.operationIds.push(operationId);
        tagMap.set(tagName, current);
      }
    }
  }

  const sortedOperations = [...operations].sort(operationSort);

  const tags: CanonicalOpenApiTagGroup[] = [...tagMap.entries()]
    .sort(([left], [right]) => compareStrings(left, right))
    .map(([name, value]) => ({
      slug: normalizeRouteSlug(name),
      name,
      description: value.description,
      routePath: `${apiRootPath}/tags/${normalizeRouteSlug(name)}`,
      operationIds: [...new Set(value.operationIds)].sort(compareStrings),
    }));

  const schemaRecord = toObject(toObject(parsed.components).schemas);
  const schemas: CanonicalOpenApiSchemaRecord[] = Object.keys(schemaRecord)
    .sort(compareStrings)
    .map((name) => {
      const schema = schemaRecord[name];
      const schemaObject = toObject(schema);
      return {
        name,
        slug: normalizeRouteSlug(name),
        routePath: `${apiRootPath}/schemas/${normalizeRouteSlug(name)}`,
        description:
          typeof schemaObject.description === "string" ? schemaObject.description : undefined,
        schema,
      };
    });

  const routes: CanonicalOpenApiRoutes = {
    overview: apiRootPath,
    tags: Object.fromEntries(tags.map((tag) => [tag.slug, tag.routePath])),
    operations: Object.fromEntries(
      sortedOperations.map((operation) => [operation.id, operation.routePath])
    ),
    schemas: Object.fromEntries(schemas.map((schema) => [schema.name, schema.routePath])),
    all: [
      apiRootPath,
      ...tags.map((tag) => tag.routePath),
      ...sortedOperations.map((operation) => operation.routePath),
      ...schemas.map((schema) => schema.routePath),
    ].sort(compareStrings),
  };

  return {
    schemaVersion: 1,
    sourceId: input.sourceId,
    sourcePath: normalizeSlug(input.sourcePath),
    sourceFormat: input.sourceFormat,
    openapiVersion,
    title,
    description: typeof info.description === "string" ? info.description : undefined,
    version: typeof info.version === "string" ? info.version : undefined,
    info: {
      title,
      description: typeof info.description === "string" ? info.description : undefined,
      version: typeof info.version === "string" ? info.version : undefined,
    },
    servers,
    tags,
    operations: sortedOperations,
    schemas,
    routes,
    diagnostics: diagnostics.sort((left, right) =>
      compareStrings(`${left.code}:${left.message}`, `${right.code}:${right.message}`)
    ),
    sourceMeta: {
      etag: input.sourceMeta?.etag,
      sha256: input.sourceMeta?.sha256,
      updatedAt: input.sourceMeta?.updatedAt,
      remoteUrl: input.sourceMeta?.remoteUrl,
    },
  };
}

export function buildOpenApiReference(
  input: BuildOpenApiReferenceInput
): CanonicalOpenApiReference {
  const parsed = parseOpenApiSource({
    sourceId: input.sourceId,
    sourcePath: input.sourcePath,
    body: input.body,
    absolutePath: input.absolutePath,
  });

  return normalizeOpenApiReference({
    sourceId: input.sourceId,
    sourcePath: input.sourcePath,
    parsed: parsed.parsed,
    sourceFormat: parsed.sourceFormat,
    fallbackTitle: input.fallbackTitle,
    basePath: input.basePath,
    sourceMeta: input.sourceMeta,
  });
}

export type OpenApiResolvedRoute =
  | { kind: "overview"; route: string }
  | { kind: "tag"; route: string; slug: string }
  | { kind: "operation"; route: string; operationId: string }
  | { kind: "schema"; route: string; schemaName: string };

export function resolveOpenApiRoute(
  reference: CanonicalOpenApiReference,
  route: string
): OpenApiResolvedRoute {
  if (route === reference.routes.overview) {
    return { kind: "overview", route };
  }

  for (const [slug, tagRoute] of Object.entries(reference.routes.tags)) {
    if (tagRoute === route) {
      return {
        kind: "tag",
        route,
        slug,
      };
    }
  }

  for (const [operationId, operationRoute] of Object.entries(reference.routes.operations)) {
    if (operationRoute === route) {
      return {
        kind: "operation",
        route,
        operationId,
      };
    }
  }

  for (const [schemaName, schemaRoute] of Object.entries(reference.routes.schemas)) {
    if (schemaRoute === route) {
      return {
        kind: "schema",
        route,
        schemaName,
      };
    }
  }

  throw createDocsError({
    code: "DOCS_ROUTE_NOT_FOUND",
    message: `API reference route ${route} was not generated`,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_ROUTE_NOT_FOUND",
        message: `API reference route ${route} was not generated`,
      }),
    ],
  });
}
","import { createDiagnostic, createDocsError } from "./diagnostics";
import type { DocsConfig, DocsVersionConfig, DocsVersionMode } from "./types";

export interface RouteBuildInput {
  collection: "docs" | "pages" | "blog" | "api";
  sourcePath: string;
  frontmatter?: Record<string, unknown>;
  config: DocsConfig;
}

export interface RouteBuildResult {
  slug: string;
  path: string;
  version?: string;
  logicalPath: string;
}

const SOURCE_EXTENSION_REGEX = /\.(md|mdx|json|yaml|yml)$/i;

export function stripSourceExtension(relativePath: string): string {
  return normalizeSlug(relativePath).replace(SOURCE_EXTENSION_REGEX, "");
}

export function normalizeSlug(value: string): string {
  return value
    .replaceAll("\\", "/")
    .split("/")
    .filter((segment) => segment.length > 0 && segment !== ".")
    .join("/");
}

export function slugToSegments(slug: string): string[] {
  const normalized = normalizeSlug(slug);
  if (!normalized) {
    return [];
  }
  return normalized.split("/");
}

export function segmentsToSlug(segments: string[]): string {
  return segments.filter(Boolean).join("/");
}

export function deriveLogicalPathFromSourcePath(sourcePath: string): string {
  const segments = slugToSegments(sourcePath);
  if (segments.length === 0) {
    return "";
  }
  if (segments[segments.length - 1] === "index") {
    return segmentsToSlug(segments.slice(0, -1));
  }
  return segmentsToSlug(segments);
}

function normalizeBasePath(basePath: string | undefined): string {
  const value = basePath && basePath.length > 0 ? basePath : "/docs";
  const prefixed = value.startsWith("/") ? value : `/${value}`;
  return prefixed.length > 1 ? prefixed.replace(/\/+$/, "") : prefixed;
}

function buildPath(basePath: string, slug: string): string {
  if (!slug) {
    return basePath;
  }
  const suffix = slug.startsWith("/") ? slug : `/${slug}`;
  return `${basePath}${suffix}`.replace(/\/{2,}/g, "/");
}

function resolveConfiguredVersions(config: DocsConfig): {
  mode: DocsVersionMode;
  versions: DocsVersionConfig[];
  defaultVersion?: DocsVersionConfig;
} {
  const mode = config.versions?.mode ?? "none";
  const versions = config.versions?.versions ?? [];
  const defaultVersion = versions.find((version) => version.default);

  if (mode !== "none" && versions.length > 0 && !defaultVersion) {
    throw createDocsError({
      code: "DOCS_VERSION_INVALID",
      message: "version mode requires exactly one default version",
      diagnostics: [
        createDiagnostic({
          code: "DOCS_VERSION_INVALID",
          message: "version mode requires exactly one default version",
        }),
      ],
    });
  }

  return {
    mode,
    versions,
    defaultVersion,
  };
}

function resolveVersionContext(input: {
  logicalPath: string;
  frontmatter?: Record<string, unknown>;
  config: DocsConfig;
}): { version?: string; slugWithoutVersion: string } {
  const { mode, versions, defaultVersion } = resolveConfiguredVersions(input.config);
  if (mode === "none" || versions.length === 0) {
    return {
      version: undefined,
      slugWithoutVersion: input.logicalPath,
    };
  }

  const validSlugs = new Set(versions.map((version) => version.slug));
  const logicalSegments = slugToSegments(input.logicalPath);
  const frontmatterVersion = input.frontmatter?.version;
  let requestedVersion: string | undefined;

  if (typeof frontmatterVersion === "string" && frontmatterVersion.length > 0) {
    if (!validSlugs.has(frontmatterVersion)) {
      throw createDocsError({
        code: "DOCS_VERSION_INVALID",
        message: `unknown configured version ${frontmatterVersion}`,
        diagnostics: [
          createDiagnostic({
            code: "DOCS_VERSION_INVALID",
            message: `unknown configured version ${frontmatterVersion}`,
          }),
        ],
      });
    }
    requestedVersion = frontmatterVersion;
  } else if (logicalSegments.length > 0 && validSlugs.has(logicalSegments[0])) {
    requestedVersion = logicalSegments[0];
  } else {
    requestedVersion = defaultVersion?.slug;
  }

  let slugWithoutVersion = input.logicalPath;
  if (
    requestedVersion &&
    logicalSegments.length > 0 &&
    logicalSegments[0] === requestedVersion
  ) {
    slugWithoutVersion = segmentsToSlug(logicalSegments.slice(1));
  }

  if (requestedVersion && slugToSegments(slugWithoutVersion)[0] === requestedVersion) {
    throw createDocsError({
      code: "DOCS_VERSION_INVALID",
      message: "version segment duplicated during route normalization",
      diagnostics: [
        createDiagnostic({
          code: "DOCS_VERSION_INVALID",
          message: "version segment duplicated during route normalization",
          details: {
            version: requestedVersion,
            logicalPath: input.logicalPath,
            normalized: slugWithoutVersion,
          },
        }),
      ],
    });
  }

  return {
    version: requestedVersion,
    slugWithoutVersion,
  };
}

function applyVersionToSlug(input: {
  slug: string;
  version?: string;
  mode: DocsVersionMode;
}): string {
  if (!input.version || input.mode === "none") {
    return input.slug;
  }

  const slugSegments = slugToSegments(input.slug);

  if (input.mode === "path-prefix") {
    return segmentsToSlug([input.version, ...slugSegments]);
  }

  if (input.mode === "path-segment") {
    return segmentsToSlug([...slugSegments, input.version]);
  }

  return input.slug;
}

export function buildRoute(input: RouteBuildInput): RouteBuildResult {
  const logicalPath = deriveLogicalPathFromSourcePath(input.sourcePath);
  const basePath = normalizeBasePath(input.config.site.basePath);

  if (input.collection === "docs") {
    const versionContext = resolveVersionContext({
      logicalPath,
      frontmatter: input.frontmatter,
      config: input.config,
    });
    const mode = input.config.versions?.mode ?? "none";
    const slug = applyVersionToSlug({
      slug: versionContext.slugWithoutVersion,
      version: versionContext.version,
      mode,
    });

    return {
      slug,
      path: buildPath(basePath, slug),
      version: versionContext.version,
      logicalPath: versionContext.slugWithoutVersion,
    };
  }

  if (input.collection === "pages") {
    const slug = logicalPath;
    return {
      slug,
      path: buildPath("", slug || "/"),
      logicalPath,
    };
  }

  if (input.collection === "blog") {
    const slug = logicalPath;
    return {
      slug,
      path: buildPath("/blog", slug),
      logicalPath,
    };
  }

  const slug = logicalPath;
  return {
    slug,
    path: buildPath("/api", slug),
    logicalPath,
  };
}

export function assertRouteAvailability(input: {
  routes: Map<string, string>;
  path: string;
  sourceId: string;
}): void {
  const existing = input.routes.get(input.path);
  if (existing && existing !== input.sourceId) {
    throw createDocsError({
      code: "DOCS_ROUTE_CONFLICT",
      message: `route ${input.path} is claimed by multiple source entries`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ROUTE_CONFLICT",
          message: `route ${input.path} is claimed by multiple source entries`,
          details: {
            route: input.path,
            firstSource: existing,
            secondSource: input.sourceId,
          },
        }),
      ],
    });
  }
}

export function buildDocsStaticParams(input: {
  routes: string[];
  basePath?: string;
  versions?: DocsConfig["versions"];
}): Array<{ slug?: string[]; version?: string }> {
  const basePath = normalizeBasePath(input.basePath);
  const versionMode = input.versions?.mode ?? "none";
  const versionSlugs = new Set(
    (input.versions?.versions ?? []).map((version) => version.slug)
  );

  return input.routes.map((route) => {
    const routeWithoutBase = route.startsWith(basePath)
      ? route.slice(basePath.length).replace(/^\/+/, "")
      : normalizeSlug(route);
    const segments = slugToSegments(routeWithoutBase);
    if (segments.length === 0) {
      return {};
    }

    if (versionMode === "path-prefix" && versionSlugs.has(segments[0])) {
      const [version, ...slug] = segments;
      return { version, slug };
    }

    if (versionMode === "path-segment" && versionSlugs.has(segments[segments.length - 1])) {
      const version = segments[segments.length - 1];
      const slug = segments.slice(0, -1);
      return { version, slug };
    }

    return { slug: segments };
  });
}
","import { createDiagnostic, createDocsError } from "./diagnostics";
import { normalizeSlug } from "./routing";
import type { DocsConfig, Sidebar, SidebarItem } from "./types";
import type { MetaDocument, MetaPageRule, NormalizedPageRecord } from "./normalize";

interface DirectoryNode {
  directory: string;
  indexPage?: NormalizedPageRecord;
  files: Map<string, NormalizedPageRecord>;
  children: Map<string, DirectoryNode>;
}

export interface NavigationBreadcrumbItem {
  label: string;
  href: string;
}

export interface NavigationPaginationLinks {
  prev?: {
    title: string;
    path: string;
  };
  next?: {
    title: string;
    path: string;
  };
}

function titleFromKey(key: string): string {
  return key
    .split(/[-_]/g)
    .map((segment) =>
      segment.length > 0
        ? `${segment.charAt(0).toUpperCase()}${segment.slice(1)}`
        : segment
    )
    .join(" ");
}

function mergeRuleLabel(rule: MetaPageRule | undefined, fallback: string): string {
  const base = rule?.label ?? fallback;
  if (rule?.icon) {
    return `${rule.icon} ${base}`;
  }
  return base;
}

function ensureDirectory(root: DirectoryNode, segments: string[]): DirectoryNode {
  let node = root;
  let currentDirectory = root.directory;
  for (const segment of segments) {
    currentDirectory = currentDirectory ? `${currentDirectory}/${segment}` : segment;
    const existing = node.children.get(segment);
    if (existing) {
      node = existing;
      continue;
    }
    const created: DirectoryNode = {
      directory: currentDirectory,
      files: new Map(),
      children: new Map(),
    };
    node.children.set(segment, created);
    node = created;
  }
  return node;
}

function buildDirectoryGraph(pages: NormalizedPageRecord[]): DirectoryNode {
  const root: DirectoryNode = {
    directory: "",
    files: new Map(),
    children: new Map(),
  };

  for (const page of pages) {
    const sourcePath = normalizeSlug(page.sourcePath);
    const segments = sourcePath.length > 0 ? sourcePath.split("/") : [];
    if (segments.length === 0 || (segments.length === 1 && segments[0] === "index")) {
      root.indexPage = page;
      continue;
    }

    if (segments[segments.length - 1] === "index") {
      const node = ensureDirectory(root, segments.slice(0, -1));
      node.indexPage = page;
      continue;
    }

    const node = ensureDirectory(root, segments.slice(0, -1));
    node.files.set(segments[segments.length - 1], page);
  }

  return root;
}

function regexFromGlob(glob: string): RegExp {
  const escaped = glob
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*\*/g, "__DOUBLE_STAR__")
    .replace(/\*/g, "[^/]*")
    .replace(/__DOUBLE_STAR__/g, ".*");

  return new RegExp(`^${escaped}$`);
}

function ruleMap(meta: MetaDocument | undefined): Map<string, MetaPageRule> {
  const mapped = new Map<string, MetaPageRule>();
  for (const pageRule of meta?.pages ?? []) {
    mapped.set(normalizeSlug(pageRule.key), pageRule);
  }
  return mapped;
}

function orderedKeys(input: {
  node: DirectoryNode;
  meta?: MetaDocument;
  strictMetaReferences?: boolean;
}): string[] {
  const existing = new Set<string>();
  if (input.node.indexPage) {
    existing.add("index");
  }
  for (const key of input.node.files.keys()) {
    existing.add(key);
  }
  for (const key of input.node.children.keys()) {
    existing.add(key);
  }

  const order: string[] = [];
  const seen = new Set<string>();
  for (const rule of input.meta?.pages ?? []) {
    const key = normalizeSlug(rule.key);
    if (!existing.has(key)) {
      if (input.strictMetaReferences ?? true) {
        throw createDocsError({
          code: "DOCS_META_INVALID",
          message: `meta.json references unknown page id ${key}`,
          diagnostics: [
            createDiagnostic({
              code: "DOCS_META_INVALID",
              message: `meta.json references unknown page id ${key}`,
              details: {
                directory: input.node.directory,
                key,
              },
            }),
          ],
        });
      }
      continue;
    }
    if (!seen.has(key)) {
      order.push(key);
      seen.add(key);
    }
  }

  const remaining = Array.from(existing).filter((key) => !seen.has(key));
  remaining.sort((left, right) => {
    if (left === "index" && right !== "index") {
      return -1;
    }
    if (right === "index" && left !== "index") {
      return 1;
    }
    return left.localeCompare(right, "en", { sensitivity: "variant", numeric: true });
  });

  return [...order, ...remaining];
}

function renderDirectory(input: {
  node: DirectoryNode;
  metaByDirectory: Map<string, MetaDocument>;
  suppressIndexForFlattening?: boolean;
  strictMetaReferences?: boolean;
}): SidebarItem[] {
  const meta = input.metaByDirectory.get(input.node.directory);
  const rules = ruleMap(meta);
  const keys = orderedKeys({
    node: input.node,
    meta,
    strictMetaReferences: input.strictMetaReferences,
  });
  const items: SidebarItem[] = [];

  for (const key of keys) {
    const rule = rules.get(key);
    if (rule?.hidden) {
      continue;
    }

    if (key === "index" && input.node.indexPage) {
      if (input.suppressIndexForFlattening) {
        continue;
      }
      items.push({
        type: "link",
        text: mergeRuleLabel(rule, input.node.indexPage.title),
        link: input.node.indexPage.path,
      });
      continue;
    }

    const filePage = input.node.files.get(key);
    if (filePage) {
      items.push({
        type: "link",
        text: mergeRuleLabel(rule, filePage.title),
        link: filePage.path,
      });
      continue;
    }

    const childDirectory = input.node.children.get(key);
    if (!childDirectory) {
      continue;
    }

    const childMeta = input.metaByDirectory.get(childDirectory.directory);
    const childItems = renderDirectory({
      node: childDirectory,
      metaByDirectory: input.metaByDirectory,
      suppressIndexForFlattening: Boolean(childMeta?.root),
      strictMetaReferences: input.strictMetaReferences,
    });
    const childLabel = mergeRuleLabel(
      rule,
      childMeta?.title ?? titleFromKey(key)
    );

    if (childMeta?.root) {
      if (childDirectory.indexPage) {
        items.push({
          type: "link",
          text: childLabel,
          link: childDirectory.indexPage.path,
        });
      }
      items.push(...childItems);
      continue;
    }

    items.push({
      type: "group",
      text: childLabel,
      items: childItems,
      expanded: false,
    });
  }

  return items;
}

export function buildSidebarFromPages(input: {
  pages: NormalizedPageRecord[];
  metaByDirectory: Map<string, MetaDocument>;
  id: string;
  strictMetaReferences?: boolean;
}): Sidebar {
  const graph = buildDirectoryGraph(input.pages);
  const items = renderDirectory({
    node: graph,
    metaByDirectory: input.metaByDirectory,
    strictMetaReferences: input.strictMetaReferences,
  });

  return {
    id: input.id,
    items,
  };
}

function matchesPattern(value: string, patterns: string[]): boolean {
  if (patterns.length === 0) {
    return true;
  }
  return patterns.some((pattern) => regexFromGlob(pattern).test(value));
}

export function buildSidebars(input: {
  pages: NormalizedPageRecord[];
  metaByDirectory: Map<string, MetaDocument>;
  config: DocsConfig;
}): Record<string, Sidebar> {
  const docsPages = input.pages.filter((page) => page.collection === "docs");
  const sidebars: Record<string, Sidebar> = {};

  sidebars.default = buildSidebarFromPages({
    pages: docsPages,
    metaByDirectory: input.metaByDirectory,
    id: "default",
    strictMetaReferences: true,
  });

  const configuredSidebars = input.config.navigation?.sidebars ?? {};
  for (const [sidebarId, definition] of Object.entries(configuredSidebars)) {
    const includePatterns = definition.include ?? [];
    const filtered = docsPages.filter((page) =>
      matchesPattern(`docs/${page.sourcePath}`, includePatterns)
    );
    sidebars[sidebarId] = buildSidebarFromPages({
      pages: filtered,
      metaByDirectory: input.metaByDirectory,
      id: sidebarId,
      strictMetaReferences: false,
    });
  }

  return sidebars;
}

export function flattenSidebarLinks(sidebar: Sidebar): Array<{ label: string; path: string }> {
  const links: Array<{ label: string; path: string }> = [];

  function walk(items: SidebarItem[]): void {
    for (const item of items) {
      if (item.type === "link" && item.link) {
        links.push({ label: item.text, path: item.link });
      } else if (item.type === "group" && item.items) {
        walk(item.items);
      }
    }
  }

  walk(sidebar.items);
  return links;
}

function findTrail(items: SidebarItem[], route: string): SidebarItem[] | null {
  for (const item of items) {
    if (item.type === "link" && item.link === route) {
      return [item];
    }

    if (item.type === "group" && item.items) {
      const child = findTrail(item.items, route);
      if (child) {
        return [item, ...child];
      }
    }
  }

  return null;
}

export function resolveBreadcrumbsFromSidebar(input: {
  sidebar: Sidebar;
  route: string;
  rootLabel?: string;
  rootHref?: string;
}): NavigationBreadcrumbItem[] {
  const links = flattenSidebarLinks(input.sidebar);
  const rootLink = links.find((link) => link.path === (input.rootHref ?? "/docs")) ?? links[0];
  const trail = findTrail(input.sidebar.items, input.route);
  if (!trail) {
    throw createDocsError({
      code: "DOCS_ROUTE_NOT_FOUND",
      message: `route ${input.route} is not present in the requested sidebar`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ROUTE_NOT_FOUND",
          message: `route ${input.route} is not present in the requested sidebar`,
          details: {
            route: input.route,
            sidebarId: input.sidebar.id,
          },
        }),
      ],
    });
  }

  const breadcrumbs: NavigationBreadcrumbItem[] = [];
  if (rootLink) {
    breadcrumbs.push({
      label: input.rootLabel ?? rootLink.label,
      href: input.rootHref ?? rootLink.path,
    });
  }

  for (const item of trail) {
    if (item.type === "group") {
      const groupFirstLink = flattenSidebarLinks({
        id: input.sidebar.id,
        items: item.items ?? [],
      })[0];
      if (groupFirstLink) {
        breadcrumbs.push({
          label: item.text,
          href: groupFirstLink.path,
        });
      }
      continue;
    }
    if (item.link) {
      const last = breadcrumbs[breadcrumbs.length - 1];
      if (last && last.href === item.link && last.label === item.text) {
        continue;
      }
      breadcrumbs.push({
        label: item.text,
        href: item.link,
      });
    }
  }

  return breadcrumbs;
}

export function resolvePaginationFromSidebar(input: {
  sidebar: Sidebar;
  route: string;
}): NavigationPaginationLinks {
  const links = flattenSidebarLinks(input.sidebar);
  const index = links.findIndex((link) => link.path === input.route);
  if (index === -1) {
    throw createDocsError({
      code: "DOCS_ROUTE_NOT_FOUND",
      message: `route ${input.route} is not present in the requested sidebar`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ROUTE_NOT_FOUND",
          message: `route ${input.route} is not present in the requested sidebar`,
          details: {
            route: input.route,
            sidebarId: input.sidebar.id,
          },
        }),
      ],
    });
  }

  return {
    prev:
      index > 0
        ? {
            title: links[index - 1].label,
            path: links[index - 1].path,
          }
        : undefined,
    next:
      index < links.length - 1
        ? {
            title: links[index + 1].label,
            path: links[index + 1].path,
          }
        : undefined,
  };
}

export function resolveSidebarForRoute(input: {
  sidebars: Record<string, Sidebar>;
  route: string;
}): string | null {
  const sidebarIds = Object.keys(input.sidebars).sort((left, right) => {
    if (left === "default" && right !== "default") {
      return 1;
    }
    if (right === "default" && left !== "default") {
      return -1;
    }
    return left.localeCompare(right, "en", { sensitivity: "variant", numeric: true });
  });

  for (const sidebarId of sidebarIds) {
    const links = flattenSidebarLinks(input.sidebars[sidebarId]);
    if (links.some((link) => link.path === input.route)) {
      return sidebarId;
    }
  }

  return null;
}
","import { extname } from "node:path";
import { createDiagnostic, createDocsError } from "./diagnostics";
import { extractHeadings } from "./markdown";
import {
  buildRoute,
  normalizeSlug,
  slugToSegments,
  stripSourceExtension,
} from "./routing";
import type {
  DocsCollection,
  DocsConfig,
  DocsSourceEntry,
  DocsSourceEntryType,
} from "./types";

export interface MetaPageRule {
  key: string;
  label?: string;
  icon?: string;
  hidden?: boolean;
}

export interface MetaDocument {
  directory: string;
  title?: string;
  description?: string;
  root?: boolean;
  pages: MetaPageRule[];
}

export interface NormalizedPageRecord {
  id: string;
  collection: "docs" | "pages";
  sourcePath: string;
  sourceDirectory: string;
  sourceName: string;
  slug: string;
  path: string;
  version?: string;
  title: string;
  description?: string;
  body: string;
  headings: Array<{ level: number; text: string; slug: string }>;
  frontmatter: Record<string, any>;
}

export interface NormalizedPostRecord {
  id: string;
  slug: string;
  path: string;
  title: string;
  date: string;
  tags: string[];
  body: string;
  frontmatter: Record<string, any>;
}

export interface NormalizedApiRecord {
  id: string;
  slug: string;
  path: string;
  title: string;
  body: string;
  frontmatter: Record<string, any>;
}

export interface NormalizedManifestInput {
  config: DocsConfig;
  entries: DocsSourceEntry[];
}

export interface NormalizedManifestData {
  pages: NormalizedPageRecord[];
  posts: NormalizedPostRecord[];
  apis: NormalizedApiRecord[];
  metaByDirectory: Map<string, MetaDocument>;
}

function shouldTreatAsContent(
  collection: DocsCollection,
  entryType: DocsSourceEntryType
): boolean {
  if (entryType !== "content") {
    return false;
  }
  return collection === "docs" || collection === "pages" || collection === "blog" || collection === "api";
}

function deriveTitleFromSourcePath(sourcePath: string): string {
  const segments = slugToSegments(sourcePath);
  const leaf = segments[segments.length - 1] ?? "untitled";
  const normalized = leaf === "index" && segments.length > 1 ? segments[segments.length - 2] : leaf;
  return normalized
    .split(/[-_]/g)
    .map((segment) =>
      segment.length > 0
        ? `${segment.charAt(0).toUpperCase()}${segment.slice(1)}`
        : segment
    )
    .join(" ");
}

function parseMetaPageRule(value: unknown): MetaPageRule {
  if (typeof value === "string") {
    return {
      key: normalizeSlug(value),
    };
  }

  if (typeof value === "object" && value !== null) {
    const record = value as Record<string, unknown>;
    const keyCandidate =
      (typeof record.id === "string" && record.id) ||
      (typeof record.key === "string" && record.key) ||
      (typeof record.page === "string" && record.page) ||
      (typeof record.name === "string" && record.name);

    if (!keyCandidate) {
      throw new Error("meta.json page rule is missing a key/id/name");
    }

    return {
      key: normalizeSlug(keyCandidate),
      label:
        typeof record.label === "string"
          ? record.label
          : typeof record.title === "string"
            ? record.title
            : undefined,
      icon: typeof record.icon === "string" ? record.icon : undefined,
      hidden: Boolean(record.hidden),
    };
  }

  throw new Error("meta.json pages entries must be strings or objects");
}

function parseMetaDocument(entry: DocsSourceEntry): MetaDocument {
  const raw = entry.body ?? "";
  const source = normalizeSlug(stripSourceExtension(entry.relativePath));
  const directory =
    source === "meta"
      ? ""
      : source.endsWith("/meta")
        ? source.slice(0, -"/meta".length)
        : source;
  let parsed: Record<string, unknown>;

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw createDocsError({
      code: "DOCS_META_INVALID",
      message: `invalid meta.json in ${entry.relativePath}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_META_INVALID",
          message: `invalid meta.json in ${entry.relativePath}`,
          location: { absolutePath: entry.absolutePath, sourceId: entry.id },
          details: {
            error: error instanceof Error ? error.message : String(error),
          },
        }),
      ],
      cause: error,
    });
  }

  const pagesValue = Array.isArray(parsed.pages) ? parsed.pages : [];
  const pages = pagesValue.map((value) => {
    try {
      return parseMetaPageRule(value);
    } catch (error) {
      throw createDocsError({
        code: "DOCS_META_INVALID",
        message: `invalid meta.json pages entry in ${entry.relativePath}`,
        diagnostics: [
          createDiagnostic({
            code: "DOCS_META_INVALID",
            message: `invalid meta.json pages entry in ${entry.relativePath}`,
            location: { absolutePath: entry.absolutePath, sourceId: entry.id },
            details: {
              error: error instanceof Error ? error.message : String(error),
            },
          }),
        ],
      });
    }
  });

  return {
    directory,
    title: typeof parsed.title === "string" ? parsed.title : undefined,
    description: typeof parsed.description === "string" ? parsed.description : undefined,
    root: Boolean(parsed.root),
    pages,
  };
}

export function normalizeSourceEntries(
  input: NormalizedManifestInput
): NormalizedManifestData {
  const pages: NormalizedPageRecord[] = [];
  const posts: NormalizedPostRecord[] = [];
  const apis: NormalizedApiRecord[] = [];
  const metaByDirectory = new Map<string, MetaDocument>();

  for (const entry of input.entries) {
    if (entry.collection === "docs" && entry.entryType === "control") {
      if (normalizeSlug(entry.relativePath).endsWith("/meta.json") || normalizeSlug(entry.relativePath) === "meta.json") {
        const parsedMeta = parseMetaDocument(entry);
        metaByDirectory.set(parsedMeta.directory, parsedMeta);
      }
      continue;
    }

    if (!shouldTreatAsContent(entry.collection, entry.entryType)) {
      continue;
    }

    const extension = extname(entry.relativePath).toLowerCase();
    const sourcePath = stripSourceExtension(entry.relativePath);
    const sourceSegments = slugToSegments(sourcePath);
    const sourceName = sourceSegments[sourceSegments.length - 1] ?? "index";
    const sourceDirectory = sourceSegments.slice(0, -1).join("/");
    const frontmatter = entry.frontmatter ?? {};

    if (
      (entry.collection === "docs" || entry.collection === "pages" || entry.collection === "blog") &&
      ![".md", ".mdx"].includes(extension)
    ) {
      continue;
    }
    if (entry.collection === "api" && ![".json", ".yaml", ".yml"].includes(extension)) {
      continue;
    }

    if (entry.collection === "docs" || entry.collection === "pages") {
      const route = buildRoute({
        collection: entry.collection,
        sourcePath,
        frontmatter,
        config: input.config,
      });

      const body = entry.body ?? "";
      pages.push({
        id: entry.id,
        collection: entry.collection,
        sourcePath,
        sourceDirectory,
        sourceName,
        slug: route.slug,
        path: route.path,
        version: route.version,
        title:
          typeof frontmatter.title === "string" && frontmatter.title.length > 0
            ? frontmatter.title
            : deriveTitleFromSourcePath(sourcePath),
        description:
          typeof frontmatter.description === "string"
            ? frontmatter.description
            : undefined,
        body,
        headings: extractHeadings(body),
        frontmatter: frontmatter as Record<string, any>,
      });
      continue;
    }

    if (entry.collection === "blog") {
      const route = buildRoute({
        collection: "blog",
        sourcePath,
        frontmatter,
        config: input.config,
      });
      posts.push({
        id: entry.id,
        slug: route.slug,
        path: route.path,
        title:
          typeof frontmatter.title === "string" && frontmatter.title.length > 0
            ? frontmatter.title
            : deriveTitleFromSourcePath(sourcePath),
        date:
          typeof frontmatter.date === "string" && frontmatter.date.length > 0
            ? frontmatter.date
            : "1970-01-01",
        tags: Array.isArray(frontmatter.tags)
          ? frontmatter.tags.filter((value) => typeof value === "string")
          : [],
        body: entry.body ?? "",
        frontmatter: frontmatter as Record<string, any>,
      });
      continue;
    }

    const route = buildRoute({
      collection: "api",
      sourcePath,
      frontmatter,
      config: input.config,
    });
    apis.push({
      id: entry.id,
      slug: route.slug,
      path: route.path,
      title:
        typeof frontmatter.title === "string" && frontmatter.title.length > 0
          ? frontmatter.title
          : deriveTitleFromSourcePath(sourcePath),
      body: entry.body ?? "",
      frontmatter: frontmatter as Record<string, any>,
    });
  }

  return {
    pages: pages.sort((left, right) =>
      left.path.localeCompare(right.path, "en", { sensitivity: "variant", numeric: true })
    ),
    posts: posts.sort((left, right) =>
      left.path.localeCompare(right.path, "en", { sensitivity: "variant", numeric: true })
    ),
    apis: apis.sort((left, right) =>
      left.path.localeCompare(right.path, "en", { sensitivity: "variant", numeric: true })
    ),
    metaByDirectory,
  };
}
","import { marked } from "marked";
import { transformFumadocsV15 } from "./compat/fumadocs";
import { createDiagnostic, createDocsError, type DocsError } from "./diagnostics";
import { assertSafeSource } from "./sanitize";
import type {
  CompiledContentArtifact,
  CompiledContentBlock,
  CompiledListBlock,
  CompiledTableBlock,
  CompiledTabsBlock,
  DocHeading,
  DocsCompatPreset,
  DocsDiagnostic,
} from "./types";

type CompileFramework = "core" | "react" | "svelte";

export interface CompileMarkdownInput {
  source: string;
  sourcePath?: string;
  framework?: CompileFramework;
  compatPreset?: DocsCompatPreset;
  allowRawHtml?: boolean;
}

const HEADING_REGEX = /^(#{1,6})\s+(.*)$/;
const CODE_FENCE_REGEX = /^```/;
const TABS_START_REGEX = /^<\s*(DocsTabs|Tabs)\b([^>]*)>/;
const TABS_END_REGEX = /^<\s*\/\s*(DocsTabs|Tabs)\s*>/;
const TAB_START_REGEX = /^<\s*(DocsTab|Tab)\b([^>]*)>/;
const TAB_END_REGEX = /^<\s*\/\s*(DocsTab|Tab)\s*>/;
const CALLOUT_REGEX = /^>\s*\[!(NOTE|TIP|WARNING|INFO|CAUTION)\]\s*(.*)$/i;
const COMPONENT_SELF_CLOSING_REGEX = /^<\s*([A-Z][A-Za-z0-9]*)\b[^>]*\/>\s*$/;
const COMPONENT_START_REGEX = /^<\s*([A-Z][A-Za-z0-9]*)\b[^>]*>\s*$/;
const LIST_UNORDERED_REGEX = /^[-*+]\s+/;
const LIST_ORDERED_REGEX = /^\d+[.)]\s+/;
const TABLE_ROW_REGEX = /^\|.+\|/;

const UNSAFE_HREF_RE = /(\bhref\s*=\s*["'])\s*javascript:[^"']*/gi;
const EVENT_ATTR_RE = /\s+on[a-z][a-z0-9]*\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]*)/gi;

interface ParseBlocksOptions {
  source: string;
  sourcePath?: string;
  resolvedComponents?: Set<string>;
  idPrefix?: string;
}

function normalizeSourceSnippet(value: string): string {
  return value.trim();
}

function normalizeRouteLikeId(value: string | undefined, fallback: string): string {
  const candidate = (value ?? fallback).replaceAll("\\", "/");
  return candidate.replace(/[^a-zA-Z0-9/_-]+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
}

function createMermaidId(input: {
  idPrefix?: string;
  sourcePath?: string;
  count: number;
}): string {
  const pathPart = normalizeRouteLikeId(input.idPrefix ?? input.sourcePath, "inline");
  return `mermaid-${pathPart}-${String(input.count).padStart(2, "0")}`;
}

function parseComponentProps(rawAttributes: string): Record<string, string | number | boolean> {
  const props: Record<string, string | number | boolean> = {};
  const pattern =
    /([A-Za-z_][A-Za-z0-9_:.-]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|\{([^}]*)\}))?/g;

  for (const match of rawAttributes.matchAll(pattern)) {
    const key = match[1];
    if (!key) {
      continue;
    }

    const stringValue = match[2] ?? match[3];
    const expressionValue = match[4]?.trim();
    if (stringValue !== undefined) {
      props[key] = stringValue;
      continue;
    }
    if (expressionValue === undefined) {
      props[key] = true;
      continue;
    }
    if (expressionValue === "true") {
      props[key] = true;
      continue;
    }
    if (expressionValue === "false") {
      props[key] = false;
      continue;
    }
    if (/^-?\d+(?:\.\d+)?$/.test(expressionValue)) {
      props[key] = Number(expressionValue);
      continue;
    }
    props[key] = expressionValue.replace(/^['"]|['"]$/g, "");
  }

  return props;
}

function sanitizeMarkdownHtml(html: string): string {
  return html
    .replace(UNSAFE_HREF_RE, "$1#")
    .replace(EVENT_ATTR_RE, "");
}

function renderInlineHtml(text: string): string {
  return sanitizeMarkdownHtml(marked.parseInline(text, { async: false }) as string);
}

function renderBlockHtml(text: string): string {
  return sanitizeMarkdownHtml(marked.parse(text.trim(), { async: false }) as string);
}

const UNICODE_SLUG_MAP: Record<string, string> = {
  日: "ri-",
  本: "ben-",
  語: "yu-",
  の: "no",
  ヘ: "he",
  テ: "d",
  デ: "d",
  ィ: "i",
  ン: "n",
  ク: "gu",
  グ: "gu",
};

function isDocsError(error: unknown): error is DocsError {
  return (
    typeof error === "object" &&
    error !== null &&
    "name" in error &&
    (error as { name: string }).name === "DocsError"
  );
}

function createMdxCompileError(input: {
  message: string;
  sourcePath?: string;
  details?: Record<string, unknown>;
}): DocsError {
  return createDocsError({
    code: "DOCS_MDX_COMPILE_FAILED",
    message: input.message,
    diagnostics: [
      createDiagnostic({
        code: "DOCS_MDX_COMPILE_FAILED",
        message: input.message,
        location: { absolutePath: input.sourcePath },
        details: input.details,
      }),
    ],
  });
}

function normalizeSlugText(text: string): string {
  let candidate = text
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[\u3099\u309a]/g, "");
  let raw = "";
  for (const character of candidate) {
    if (UNICODE_SLUG_MAP[character]) {
      raw += UNICODE_SLUG_MAP[character];
      continue;
    }
    if (/[A-Za-z0-9]/.test(character)) {
      raw += character.toLowerCase();
      continue;
    }
    if (/[\s\-_/&()[\]{}.,:;!?'"`~+*<>=|\\]/.test(character)) {
      raw += "-";
      continue;
    }
    raw += `u${character.codePointAt(0)?.toString(16) ?? ""}-`;
  }

  const normalized = raw.replace(/-+/g, "-").replace(/(^-|-$)/g, "");
  return normalized || "section";
}

function createSlugger(): (text: string) => string {
  const seen = new Map<string, number>();
  return (text: string) => {
    const base = normalizeSlugText(text);
    const count = seen.get(base) ?? 0;
    seen.set(base, count + 1);
    return count === 0 ? base : `${base}-${count}`;
  };
}

function isListStart(line: string): boolean {
  const trimmed = line.trim();
  return LIST_UNORDERED_REGEX.test(trimmed) || LIST_ORDERED_REGEX.test(trimmed);
}

function isTableStart(line: string): boolean {
  return TABLE_ROW_REGEX.test(line.trim());
}

function isBlockStart(line: string): boolean {
  const trimmed = line.trim();
  return (
    trimmed.length === 0 ||
    HEADING_REGEX.test(trimmed) ||
    CODE_FENCE_REGEX.test(trimmed) ||
    TABS_START_REGEX.test(trimmed) ||
    CALLOUT_REGEX.test(trimmed) ||
    COMPONENT_SELF_CLOSING_REGEX.test(trimmed) ||
    COMPONENT_START_REGEX.test(trimmed) ||
    isListStart(line) ||
    isTableStart(line)
  );
}

function parseTableBlock(input: {
  lines: string[];
  startIndex: number;
}): { block: CompiledTableBlock; nextIndex: number } {
  const rawLines: string[] = [];
  let index = input.startIndex;

  while (index < input.lines.length) {
    const trimmed = input.lines[index].trim();
    if (trimmed.length === 0 || !TABLE_ROW_REGEX.test(trimmed)) {
      break;
    }
    rawLines.push(input.lines[index]);
    index++;
  }

  const html = renderBlockHtml(rawLines.join("\n"));
  return { block: { type: "table", html }, nextIndex: index };
}

function parseListBlock(input: {
  lines: string[];
  startIndex: number;
}): { block: CompiledListBlock; nextIndex: number } {
  const firstTrimmed = input.lines[input.startIndex].trim();
  const ordered = LIST_ORDERED_REGEX.test(firstTrimmed);
  const rawLines: string[] = [];
  const items: Array<{ text: string }> = [];
  let index = input.startIndex;

  while (index < input.lines.length) {
    const rawLine = input.lines[index];
    const trimmed = rawLine.trim();

    if (trimmed.length === 0) {
      // Blank line: part of a loose list only if next non-blank is a list line or indented continuation
      let peek = index + 1;
      while (peek < input.lines.length && input.lines[peek].trim().length === 0) {
        peek++;
      }
      if (peek < input.lines.length) {
        const nextLine = input.lines[peek];
        const nextTrimmed = nextLine.trim();
        const nextIsListContinuation =
          LIST_UNORDERED_REGEX.test(nextTrimmed) ||
          LIST_ORDERED_REGEX.test(nextTrimmed) ||
          nextLine.startsWith("  ") ||
          nextLine.startsWith("\t");
        if (nextIsListContinuation) {
          rawLines.push(rawLine);
          index = peek;
          continue;
        }
      }
      break;
    }

    const isTopLevel =
      (LIST_UNORDERED_REGEX.test(trimmed) || LIST_ORDERED_REGEX.test(trimmed)) &&
      !rawLine.startsWith("  ") &&
      !rawLine.startsWith("\t");
    const isIndentedContinuation =
      (rawLine.startsWith("  ") || rawLine.startsWith("\t")) && rawLines.length > 0;

    if (!isTopLevel && !isIndentedContinuation) {
      break;
    }

    if (isTopLevel) {
      const text = trimmed
        .replace(LIST_UNORDERED_REGEX, "")
        .replace(LIST_ORDERED_REGEX, "")
        .trim();
      items.push({ text });
    }

    rawLines.push(rawLine);
    index++;
  }

  const html = renderBlockHtml(rawLines.join("\n"));
  return { block: { type: "list", ordered, items, html }, nextIndex: index };
}

function parseTabsItems(rawAttributes: string): string[] {
  const itemsMatch = rawAttributes.match(/items\s*=\s*\{(\[[^\]]*\])\}/);
  if (!itemsMatch) {
    return [];
  }

  const literal = itemsMatch[1].replaceAll("'", "\"");
  try {
    const parsed = JSON.parse(literal);
    if (!Array.isArray(parsed)) {
      return [];
    }
    return parsed.filter((value) => typeof value === "string");
  } catch {
    return [];
  }
}

function parseTabsBlock(input: {
  lines: string[];
  startIndex: number;
  sourcePath?: string;
  resolvedComponents?: Set<string>;
  idPrefix?: string;
}): { block: CompiledTabsBlock; nextIndex: number } {
  const startLine = input.lines[input.startIndex].trim();
  const startMatch = startLine.match(TABS_START_REGEX);
  if (!startMatch) {
    throw createMdxCompileError({
      message: "invalid tabs block start",
      sourcePath: input.sourcePath,
    });
  }

  const tabs: CompiledTabsBlock["tabs"] = [];
  const declaredItems = parseTabsItems(startMatch[2] ?? "");
  let index = input.startIndex + 1;
  let foundClosing = false;

  while (index < input.lines.length) {
    const line = input.lines[index].trim();
    if (TABS_END_REGEX.test(line)) {
      foundClosing = true;
      index += 1;
      break;
    }

    const tabStartMatch = line.match(TAB_START_REGEX);
    if (!tabStartMatch) {
      index += 1;
      continue;
    }

    const tabAttributes = tabStartMatch[2] ?? "";
    const valueMatch = tabAttributes.match(/value\s*=\s*["']([^"']+)["']/);
    const value = valueMatch?.[1];
    if (!value) {
      throw createMdxCompileError({
        message: "tab block is missing required value attribute",
        sourcePath: input.sourcePath,
      });
    }

    const inlineContentMatch = line.match(
      /<\s*(DocsTab|Tab)\b[^>]*>([\s\S]*?)<\s*\/\s*(DocsTab|Tab)\s*>/
    );
    if (inlineContentMatch) {
      const source = normalizeSourceSnippet(inlineContentMatch[2] ?? "");
      tabs.push({
        value,
        label: declaredItems.includes(value) ? value : undefined,
        source,
        content: source,
        nodes: parseBlocks({
          source,
          sourcePath: input.sourcePath,
          resolvedComponents: input.resolvedComponents,
          idPrefix: `${normalizeRouteLikeId(input.idPrefix ?? input.sourcePath, "inline")}-tab-${String(tabs.length + 1).padStart(2, "0")}`,
        }),
      });
      index += 1;
      continue;
    }

    const contentLines: string[] = [];
    index += 1;
    let foundTabClose = false;
    while (index < input.lines.length) {
      const tabLine = input.lines[index];
      if (TAB_END_REGEX.test(tabLine.trim())) {
        foundTabClose = true;
        index += 1;
        break;
      }
      contentLines.push(tabLine);
      index += 1;
    }

    if (!foundTabClose) {
      throw createMdxCompileError({
        message: "tab block is missing a closing tag",
        sourcePath: input.sourcePath,
      });
    }

    const source = normalizeSourceSnippet(contentLines.join("\n"));
    tabs.push({
      value,
      label: declaredItems.includes(value) ? value : undefined,
      source,
      content: source,
      nodes: parseBlocks({
        source,
        sourcePath: input.sourcePath,
        resolvedComponents: input.resolvedComponents,
        idPrefix: `${normalizeRouteLikeId(input.idPrefix ?? input.sourcePath, "inline")}-tab-${String(tabs.length + 1).padStart(2, "0")}`,
      }),
    });
  }

  if (!foundClosing) {
    throw createMdxCompileError({
      message: "tabs block is missing a closing tag",
      sourcePath: input.sourcePath,
    });
  }

  if (tabs.length === 0) {
    throw createMdxCompileError({
      message: "tabs block does not contain any tab items",
      sourcePath: input.sourcePath,
    });
  }

  const items = declaredItems.length > 0 ? declaredItems : tabs.map((tab) => tab.value);
  return {
    block: {
      type: "tabs",
      items,
      tabs,
    },
    nextIndex: index,
  };
}

function parseBlocks(input: ParseBlocksOptions): CompiledContentBlock[] {
  const lines = input.source.split(/\r?\n/);
  const blocks: CompiledContentBlock[] = [];
  const createHeadingSlug = createSlugger();
  let mermaidCount = 0;
  let tabsBlockCount = 0;
  let componentBlockCount = 0;
  let index = 0;

  while (index < lines.length) {
    const rawLine = lines[index];
    const trimmed = rawLine.trim();

    if (trimmed.length === 0) {
      index += 1;
      continue;
    }

    if (CODE_FENCE_REGEX.test(trimmed)) {
      const lang = trimmed.slice(3).trim() || undefined;
      index += 1;
      const codeLines: string[] = [];
      let foundFenceClose = false;
      while (index < lines.length) {
        const codeLine = lines[index];
        if (CODE_FENCE_REGEX.test(codeLine.trim())) {
          foundFenceClose = true;
          index += 1;
          break;
        }
        codeLines.push(codeLine);
        index += 1;
      }
      if (!foundFenceClose) {
        throw createMdxCompileError({
          message: "code fence is missing a closing delimiter",
          sourcePath: input.sourcePath,
        });
      }
      const code = codeLines.join("\n");
      if (lang?.toLowerCase() === "mermaid") {
        mermaidCount += 1;
        blocks.push({
          type: "mermaid",
          id: createMermaidId({
            idPrefix: input.idPrefix,
            sourcePath: input.sourcePath,
            count: mermaidCount,
          }),
          code,
        });
      } else {
        blocks.push({ type: "code", lang, code });
      }
      continue;
    }

    const headingMatch = trimmed.match(HEADING_REGEX);
    if (headingMatch) {
      const level = headingMatch[1].length;
      const text = headingMatch[2].trim();
      blocks.push({
        type: "heading",
        level,
        text,
        html: renderInlineHtml(text),
        slug: createHeadingSlug(text),
      });
      index += 1;
      continue;
    }

    if (isListStart(trimmed)) {
      const parsedList = parseListBlock({ lines, startIndex: index });
      blocks.push(parsedList.block);
      index = parsedList.nextIndex;
      continue;
    }

    if (TABS_START_REGEX.test(trimmed)) {
      tabsBlockCount += 1;
      const parsedTabs = parseTabsBlock({
        lines,
        startIndex: index,
        sourcePath: input.sourcePath,
        resolvedComponents: input.resolvedComponents,
        idPrefix: `${normalizeRouteLikeId(input.idPrefix ?? input.sourcePath, "inline")}-tabs-${String(tabsBlockCount).padStart(2, "0")}`,
      });
      blocks.push(parsedTabs.block);
      index = parsedTabs.nextIndex;
      continue;
    }

    const calloutMatch = trimmed.match(CALLOUT_REGEX);
    if (calloutMatch) {
      const calloutLines: string[] = [];
      const firstLine = calloutMatch[2]?.trim() ?? "";
      if (firstLine) {
        calloutLines.push(firstLine);
      }
      index += 1;
      while (index < lines.length && lines[index].trim().startsWith(">")) {
        const value = lines[index].replace(/^\s*>\s?/, "").trim();
        if (value) {
          calloutLines.push(value);
        }
        index += 1;
      }
      const calloutText = calloutLines.join("\n");
      blocks.push({
        type: "callout",
        kind: calloutMatch[1].toLowerCase() as "note" | "tip" | "warning" | "info" | "caution",
        text: calloutText,
        html: renderBlockHtml(calloutText),
      });
      continue;
    }

    const selfClosingComponentMatch = trimmed.match(COMPONENT_SELF_CLOSING_REGEX);
    if (selfClosingComponentMatch) {
      const componentName = selfClosingComponentMatch[1];
      if (
        input.resolvedComponents &&
        !input.resolvedComponents.has(componentName)
      ) {
        throw createDocsError({
          code: "DOCS_COMPONENT_UNRESOLVED",
          message: `component ${componentName} is not resolved in compatibility mode`,
          diagnostics: [
            createDiagnostic({
              code: "DOCS_COMPONENT_UNRESOLVED",
              message: `component ${componentName} is not resolved in compatibility mode`,
              location: { absolutePath: input.sourcePath },
              details: {
                component: componentName,
              },
            }),
          ],
        });
      }
      blocks.push({
        type: "component",
        name: componentName,
        props: parseComponentProps(
          trimmed.replace(/^<\s*[A-Z][A-Za-z0-9]*/, "").replace(/\/>\s*$/, "")
        ),
        source: "",
        body: undefined,
        selfClosing: true,
        children: [],
      });
      index += 1;
      continue;
    }

    const componentStartMatch = trimmed.match(COMPONENT_START_REGEX);
    if (componentStartMatch) {
      const componentName = componentStartMatch[1];
      componentBlockCount += 1;
      if (
        input.resolvedComponents &&
        !input.resolvedComponents.has(componentName)
      ) {
        throw createDocsError({
          code: "DOCS_COMPONENT_UNRESOLVED",
          message: `component ${componentName} is not resolved in compatibility mode`,
          diagnostics: [
            createDiagnostic({
              code: "DOCS_COMPONENT_UNRESOLVED",
              message: `component ${componentName} is not resolved in compatibility mode`,
              location: { absolutePath: input.sourcePath },
              details: {
                component: componentName,
              },
            }),
          ],
        });
      }
      index += 1;
      const bodyLines: string[] = [];
      let foundComponentClose = false;
      const componentClosePattern = new RegExp(`^<\\s*\\/\\s*${componentName}\\s*>\\s*$`);
      while (index < lines.length) {
        const current = lines[index];
        if (componentClosePattern.test(current.trim())) {
          foundComponentClose = true;
          index += 1;
          break;
        }
        bodyLines.push(current);
        index += 1;
      }
      if (!foundComponentClose) {
        throw createMdxCompileError({
          message: `component ${componentName} is missing a closing tag`,
          sourcePath: input.sourcePath,
        });
      }
      const source = normalizeSourceSnippet(bodyLines.join("\n"));
      blocks.push({
        type: "component",
        name: componentName,
        props: parseComponentProps(
          trimmed.replace(/^<\s*[A-Z][A-Za-z0-9]*/, "").replace(/>\s*$/, "")
        ),
        source,
        body: source,
        selfClosing: false,
        children: parseBlocks({
          source,
          sourcePath: input.sourcePath,
          resolvedComponents: input.resolvedComponents,
          idPrefix: `${normalizeRouteLikeId(input.idPrefix ?? input.sourcePath, "inline")}-component-${componentName}-${String(componentBlockCount).padStart(2, "0")}`,
        }),
      });
      continue;
    }

    if (isTableStart(trimmed)) {
      const parsedTable = parseTableBlock({ lines, startIndex: index });
      blocks.push(parsedTable.block);
      index = parsedTable.nextIndex;
      continue;
    }

    const paragraphLines: string[] = [];
    while (index < lines.length && !isBlockStart(lines[index])) {
      paragraphLines.push(lines[index].trim());
      index += 1;
    }
    if (paragraphLines.length > 0) {
      const paragraphText = paragraphLines.join(" ").trim();
      blocks.push({
        type: "paragraph",
        text: paragraphText,
        html: renderInlineHtml(paragraphText),
      });
