  searchAll(params: {
    query: string;
    resources: string[];
    limit: number;
    limitPerResource: number;
    prefix: boolean;
  }): Promise<SearchHit[]>;
}

interface SnapshotSearchEngine {
  importSnapshot(snapshot: DocsSearchArtifact["snapshot"]): void;
  searchDetailed(
    query: string,
    options: {
      fields?: string[];
      limit?: number;
    }
  ): Array<{ docId: string | number; score: number }>;
}

interface SearchFnClientModule {
  InMemorySearchFn: new (options: {
    fields: string[];
    pipeline?: {
      enableEdgeNGrams?: boolean;
      edgeNGramMinLength?: number;
    };
  }) => SnapshotSearchEngine;
  createMemorySearchClient(config?: {
    adapterConfig?: {
      pipeline?: {
        enableEdgeNGrams?: boolean;
        edgeNGramMinLength?: number;
      };
    };
    defaults?: {
      prefix?: boolean;
      limit?: number;
      limitPerResource?: number;
    };
  }): SearchClient;
}

async function loadSearchFnClient(): Promise<SearchFnClientModule> {
  try {
    return (await import("@searchfn/client")) as unknown as SearchFnClientModule;
  } catch (error) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: "@searchfn/client is required to query a docs search artifact",
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: "@searchfn/client is required to query a docs search artifact",
          suggestion:
            "Install @searchfn/client or avoid creating the docs search runtime on pages that do not use search.",
        }),
      ],
      cause: error,
    });
  }
}

function assertValidArtifact(artifact: DocsSearchArtifact): void {
  if (artifact.schemaVersion !== 1 || artifact.engine !== "searchfn") {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: "search artifact schema is invalid",
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: "search artifact schema is invalid",
        }),
      ],
    });
  }

  if (!Array.isArray(artifact.documents) || !artifact.snapshot) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: "search artifact is malformed",
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: "search artifact is malformed",
        }),
      ],
    });
  }
}

async function createSearchClientForArtifact(): Promise<SearchClient> {
  const { createMemorySearchClient } = await loadSearchFnClient();
  return createMemorySearchClient({
    adapterConfig: {
      pipeline: {
        enableEdgeNGrams: true,
        edgeNGramMinLength: 2,
      },
    },
    defaults: {
      prefix: true,
      limit: 20,
      limitPerResource: 20,
    },
  });
}

async function createSnapshotSearchEngine(artifact: DocsSearchArtifact): Promise<SnapshotSearchEngine> {
  const { InMemorySearchFn } = await loadSearchFnClient();
  const engine = new InMemorySearchFn({
    fields: artifact.fields,
    pipeline: {
      enableEdgeNGrams: true,
      edgeNGramMinLength: 2,
    },
  });
  engine.importSnapshot(artifact.snapshot);
  return engine;
}

function sortResults(
  results: DocsSearchRuntimeResultItem[],
  limit: number
): DocsSearchRuntimeResultItem[] {
  return [...results]
    .sort((left, right) => {
      if (right.score !== left.score) {
        return right.score - left.score;
      }
      const titleCompare = left.title.localeCompare(right.title, "en", {
        sensitivity: "variant",
        numeric: true,
      });
      if (titleCompare !== 0) {
        return titleCompare;
      }
      const pathCompare = left.path.localeCompare(right.path, "en", {
        sensitivity: "variant",
        numeric: true,
      });
      if (pathCompare !== 0) {
        return pathCompare;
      }
      return left.id.localeCompare(right.id, "en", {
        sensitivity: "variant",
        numeric: true,
      });
    })
    .slice(0, Math.max(1, limit));
}

export function createDocsSearchRuntime(
  input: CreateDocsSearchRuntimeInput
): DocsSearchRuntime {
  let validated: ValidatedArtifact | null = null;
  let loadingPromise: Promise<ValidatedArtifact> | null = null;

  async function loadValidated(): Promise<ValidatedArtifact> {
    if (validated) {
      return validated;
    }
    if (loadingPromise) {
      return loadingPromise;
    }

    loadingPromise = (async () => {
      const artifact = input.artifact ?? (input.loadArtifact ? await input.loadArtifact() : null);
      if (!artifact) {
        throw createDocsError({
          code: "DOCS_ARTIFACT_INVALID",
          message: "search runtime was created without an artifact or loader",
          diagnostics: [
            createDiagnostic({
              code: "DOCS_ARTIFACT_INVALID",
              message: "search runtime was created without an artifact or loader",
            }),
          ],
        });
      }

      assertValidArtifact(artifact);
      const documents = new Map<string, DocsSearchDocument>();

      for (const document of artifact.documents) {
        documents.set(document.id, document);
      }

      if (artifact.schemaVersion === 1 && artifact.snapshot) {
        validated = {
          artifact,
          client: null,
          engine: await createSnapshotSearchEngine(artifact),
          documents,
        };
        return validated;
      }

      const client = await createSearchClientForArtifact();
      await client.initialize?.({
        resources: artifact.scopes.map((scope) => ({
          name: scope,
          searchFields: artifact.fields,
        })),
      });

      for (const scope of artifact.scopes) {
        const scopedDocuments = artifact.documents.filter((document) => document.scope === scope);
        if (scopedDocuments.length === 0) {
          continue;
        }
        await client.index({
          resource: scope,
          documents: scopedDocuments.map((document) => ({
            id: document.id,
            fields: {
              title: document.title,
              summary: document.summary,
              headings: document.headings.join(" "),
              tags: document.tags.join(" "),
              body: document.body,
            },
          })),
        });
      }

      validated = { artifact, client, engine: null, documents };
      return validated;
    })();

    try {
      return await loadingPromise;
    } finally {
      loadingPromise = null;
    }
  }

  return {
    async ensureReady(): Promise<void> {
      await loadValidated();
    },
    async getScopes(): Promise<DocsSearchScope[]> {
      const loaded = await loadValidated();
      return [...loaded.artifact.scopes];
    },
    async query(queryInput: DocsSearchRuntimeQueryInput): Promise<DocsSearchRuntimeResultItem[]> {
      const loaded = await loadValidated();
      const normalizedQuery = queryInput.query.trim();
      if (!normalizedQuery) {
        return [];
      }

      const scope = queryInput.scope ?? "all";
      if (scope !== "all" && !loaded.artifact.scopes.includes(scope)) {
        throw createDocsError({
          code: "DOCS_CONFIG_INVALID",
          message: `unknown search scope ${scope}`,
          diagnostics: [
            createDiagnostic({
              code: "DOCS_CONFIG_INVALID",
              message: `unknown search scope ${scope}`,
            }),
          ],
        });
      }

      if (loaded.engine) {
        const engineResults = loaded.engine.searchDetailed(normalizedQuery, {
          fields: loaded.artifact.fields,
          limit: loaded.artifact.documents.length || Math.max(queryInput.limit ?? 20, 20),
        });
        const mapped = engineResults
          .map((hit) => {
            const document = loaded.documents.get(String(hit.docId));
            if (!document) {
              return null;
            }
            return {
              id: document.id,
              score: hit.score,
              scope: document.scope,
              kind: document.kind,
              path: document.path,
              title: document.title,
              summary: document.summary,
            };
          })
          .filter((item): item is DocsSearchRuntimeResultItem => item !== null)
          .filter((item) => item.path.length > 0 && item.title.length > 0)
          .filter((item) => scope === "all" || item.scope === scope);

        return sortResults(mapped, queryInput.limit ?? 20);
      }

      if (!loaded.client) {
        throw createDocsError({
          code: "DOCS_ARTIFACT_INVALID",
          message: "search runtime backend is unavailable",
          diagnostics: [
            createDiagnostic({
              code: "DOCS_ARTIFACT_INVALID",
              message: "search runtime backend is unavailable",
            }),
          ],
        });
      }

      const resources = scope === "all" ? loaded.artifact.scopes : [scope];
      const hits = await loaded.client.searchAll({
        query: normalizedQuery,
        resources,
        limit: Math.max(queryInput.limit ?? 20, 20),
        limitPerResource: Math.max(queryInput.limit ?? 20, 20),
        prefix: true,
      });
      const mapped = hits
        .map((hit) => {
          const document = loaded.documents.get(String(hit.id));
          if (!document) {
            return null;
          }
          return {
            id: document.id,
            score: hit.score,
            scope: document.scope,
            kind: document.kind,
            path: document.path,
            title: document.title,
            summary: document.summary,
          };
        })
        .filter((item): item is DocsSearchRuntimeResultItem => item !== null)
        .filter((item) => item.path.length > 0 && item.title.length > 0)
        .filter((item) => scope === "all" || item.scope === scope);

      return sortResults(mapped, queryInput.limit ?? 20);
    },
  };
}
","import {
  resolveBreadcrumbsFromSidebar,
  resolvePaginationFromSidebar,
  resolveSidebarForRoute,
} from "./navigation";
import type { DocPage, DocsManifest, DocsTopNavItem, Sidebar } from "./types";

export interface BreadcrumbItem {
  label: string;
  href: string;
}

export interface PaginationLinks {
  prev?: {
    title: string;
    path: string;
  };
  next?: {
    title: string;
    path: string;
  };
}

type ManifestNavigationInput = Pick<DocsManifest, "pages" | "sidebars">;

function isManifestNavigationInput(
  value: Record<string, DocPage> | ManifestNavigationInput
): value is ManifestNavigationInput {
  return (
    typeof value === "object" &&
    value !== null &&
    "sidebars" in value &&
    typeof (value as ManifestNavigationInput).sidebars === "object" &&
    (value as ManifestNavigationInput).sidebars !== null
  );
}

interface PaginationOverride {
  path: string;
  title?: string;
}

function normalizePaginationOverride(
  input: unknown
): PaginationOverride | undefined {
  if (typeof input === "string" && input.length > 0) {
    return { path: input };
  }

  if (typeof input !== "object" || input === null) {
    return undefined;
  }

  const candidate = input as Record<string, unknown>;
  const pathCandidate =
    (typeof candidate.path === "string" && candidate.path) ||
    (typeof candidate.href === "string" && candidate.href);

  if (!pathCandidate) {
    return undefined;
  }

  return {
    path: pathCandidate,
    title: typeof candidate.title === "string" ? candidate.title : undefined,
  };
}

function resolveTitleForPath(
  path: string,
  pages: Record<string, DocPage>,
  fallback: string
): string {
  const page = Object.values(pages).find((candidate) => candidate.path === path);
  return page?.title ?? fallback;
}

export function generateBreadcrumbs(
  path: string,
  pagesOrManifest: Record<string, DocPage> | ManifestNavigationInput,
  options: {
    homeLabel?: string;
    homeHref?: string;
    sidebarId?: string;
  } = {}
): BreadcrumbItem[] {
  const { homeLabel, homeHref } = options;
  if (
    isManifestNavigationInput(pagesOrManifest) &&
    Object.keys(pagesOrManifest.sidebars).length > 0
  ) {
    const selectedSidebarId =
      options.sidebarId ??
      resolveSidebarForRoute({
        sidebars: pagesOrManifest.sidebars,
        route: path,
      }) ??
      "default";
    const selectedSidebar = pagesOrManifest.sidebars[selectedSidebarId];
    if (selectedSidebar) {
      return resolveBreadcrumbsFromSidebar({
        sidebar: selectedSidebar,
        route: path,
        rootLabel: homeLabel,
        rootHref: homeHref,
      });
    }
  }

  const pages = isManifestNavigationInput(pagesOrManifest)
    ? pagesOrManifest.pages
    : pagesOrManifest;
  const fallbackHomeLabel = homeLabel ?? "Home";
  const fallbackHomeHref = homeHref ?? "/";
  const crumbs: BreadcrumbItem[] = [{ label: fallbackHomeLabel, href: fallbackHomeHref }];
  const segments = path.split("/").filter(Boolean);
  let currentPath = "";

  for (const segment of segments) {
    currentPath += `/${segment}`;
    const page = Object.values(pages).find((candidate) => candidate.path === currentPath);
    if (page) {
      crumbs.push({ label: page.title, href: currentPath });
      continue;
    }
    crumbs.push({
      label: segment
        .split("-")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" "),
      href: currentPath,
    });
  }

  return crumbs;
}

export function getPaginationFromSidebar(
  currentPath: string,
  sidebar: Sidebar
): PaginationLinks {
  try {
    return resolvePaginationFromSidebar({
      sidebar,
      route: currentPath,
    });
  } catch {
    return {};
  }
}

export function getPaginationFromSidebarWithTitles(
  currentPath: string,
  sidebar: Sidebar,
  pages: Record<string, DocPage>
): PaginationLinks {
  const currentPage = Object.values(pages).find((page) => page.path === currentPath);
  const previousOverride = normalizePaginationOverride(currentPage?.frontmatter?.prev);
  const nextOverride = normalizePaginationOverride(currentPage?.frontmatter?.next);

  if (previousOverride || nextOverride) {
    return {
      prev: previousOverride
        ? {
            path: previousOverride.path,
            title: previousOverride.title
              ? previousOverride.title
              : resolveTitleForPath(previousOverride.path, pages, previousOverride.path),
          }
        : undefined,
      next: nextOverride
        ? {
            path: nextOverride.path,
            title: nextOverride.title
              ? nextOverride.title
              : resolveTitleForPath(nextOverride.path, pages, nextOverride.path),
          }
        : undefined,
    };
  }

  const pagination = getPaginationFromSidebar(currentPath, sidebar);
  if (pagination.prev) {
    pagination.prev.title = resolveTitleForPath(
      pagination.prev.path,
      pages,
      pagination.prev.title
    );
  }
  if (pagination.next) {
    pagination.next.title = resolveTitleForPath(
      pagination.next.path,
      pages,
      pagination.next.title
    );
  }

  return pagination;
}

export function getTopNavigation(
  manifest: Pick<DocsManifest, "topNav">
): DocsTopNavItem[] {
  return manifest.topNav ?? [];
}
