  enabledColor: boolean
): Spinner {
  const frames = ["-", "\\", "|", "/"];
  let timer: NodeJS.Timeout | null = null;
  let frameIndex = 0;
  let current = message;

  const render = () => {
    writer(`\r${frames[frameIndex % frames.length]} ${current}`);
