import {
  createAdminCapabilityAdapter,
  defineAdminCapability
} from '@superfunctions/admin';

export const cliFnAdminCapability = defineAdminCapability({
  schemaVersion: '1.0',
  id: 'clifn',
  displayName: 'CliFn',
  version: '0.1.0',
  description: 'CliFn administration availability for Super Console installations.',
  category: 'developer-tools',
  availability: 'unavailable',
  unavailableReason:
    'CliFn currently provides process-local CLI configuration, credentials, diagnostics, and command execution utilities, but no server-side operator service with a durable authorization boundary. Exposing those utilities would create an unsafe remote shell or local-secret surface.',
  scopeLevels: ['installation'],
  operations: []
});

export const cliFnAdminAdapter = createAdminCapabilityAdapter(
  cliFnAdminCapability,
  {}
);

export const adminCapability = cliFnAdminCapability;
export const adminAdapter = cliFnAdminAdapter;
import { Writable } from "node:stream";

export class InvalidJsonStdinError extends Error {
  readonly code = "CLIFN_INVALID_STDIN_JSON";

  constructor(message: string) {
    super(message);
    this.name = "InvalidJsonStdinError";
  }
}

async function readAll(stream: NodeJS.ReadableStream): Promise<string> {
  return await new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    stream.on("data", (chunk) => {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
    });
    stream.on("error", reject);
    stream.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
  });
}

export async function readJsonStdin<T>(input: NodeJS.ReadableStream = process.stdin): Promise<T> {
  const raw = (await readAll(input)).trim();
  if (raw.length === 0) {
    throw new InvalidJsonStdinError("stdin is empty; expected one JSON document");
  }
  try {
    return JSON.parse(raw) as T;
  } catch (error) {
    const message = error instanceof Error ? error.message : "unknown parse error";
    throw new InvalidJsonStdinError(`stdin contains invalid JSON: ${message}`);
  }
}

export function writeJsonStdout<T>(value: T, output: Writable = process.stdout): void {
  output.write(`${JSON.stringify(value)}\n`);
}
import { createOutput, type Spinner } from "./output.js";
export type { Spinner } from "./output.js";

function getOutput() {
  return createOutput();
}

export const ui = {
  success(message: string): void {
    getOutput().success(message);
  },
  error(message: string): void {
    getOutput().error(message);
  },
  warn(message: string): void {
    getOutput().warn(message);
  },
  info(message: string): void {
    getOutput().info(message);
  },
  spinner(message: string): Spinner {
    return getOutput().spinner(message);
  },
  table(rows: Array<Record<string, string | number | boolean | null | undefined>>): void {
    const columns = rows.length === 0 ? [] : Object.keys(rows[0]);
    getOutput().table({ columns, rows });
  },
};

